// ============================================================
//  HEADER + TAB BAR
// ============================================================
const Header = ({ title, subtitle, leftAction, rightAction }: {
  title: any;
  subtitle?: any;
  leftAction?: any;
  rightAction?: any;
}) => {
  const renderAction = (action) => {
    if (!action) return null;
    if (React.isValidElement(action)) return action;
    if (action.icon && action.onClick) {
      return (
        <button
          type="button"
          onClick={action.onClick}
          className="rounded-full bbp-tap flex items-center justify-center"
          style={{
            width: 38, height: 38,
            color: C.coffee,
            background: C.paper,
            border: `1px solid ${C.hairline}`,
          }}
        >
          {action.icon}
        </button>
      );
    }
    return null;
  };

  // When the caller doesn't pass a title we treat the header as a
  // "hero" — the Braid Boss Pro brand line scales up and becomes the
  // focal point. Used by the Home dashboard, which no longer needs
  // the "Good morning" greeting (the hero card below already covers
  // that with the Welcome-back copy).
  const hasTitle = title !== undefined && title !== null && title !== "";
  return (
    <header
      className="px-4 sticky top-0 z-10"
      style={{
        background: C.cream,
        borderBottom: `1px solid ${C.hairline}`,
        // Honor iOS notch / dynamic island. Adds the env inset on
        // top of a flat 12px so the brand line never collides with
        // the status bar but doesn't add dead space when the safe
        // area is 0 (Android, desktop).
        paddingTop: "calc(env(safe-area-inset-top, 0px) + 10px)",
        paddingBottom: 10,
      }}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="w-10 flex justify-start">{renderAction(leftAction)}</div>
        <div className="text-center flex-1 min-w-0 px-1">
          {hasTitle ? (
            <>
              <p className="text-[10px] font-bold tracking-[0.20em] uppercase" style={{ color: C.brandPrimary, letterSpacing: "0.20em" }}>Braid Boss Pro</p>
              <h1 className="truncate" style={{ fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 600, color: C.espresso, lineHeight: 1.15, marginTop: 1 }}>{title}</h1>
            </>
          ) : (
            // Dashboard hero brand. Single-line brand mark — the
            // welcome card below carries the greeting, so the
            // header stays compact (one row of brand + a date
            // subtitle).
            <h1
              className="font-bold uppercase truncate"
              style={{
                fontSize: 17,
                letterSpacing: "0.12em",
                color: C.brandPrimary,
                lineHeight: 1.2,
              }}
            >
              Braid Boss Pro
            </h1>
          )}
          {subtitle && (
            // Subtitle may be a plain date string or a compound
            // (date + cloud-backup pill). Render as flex-wrap so
            // the pill drops below the date on narrow viewports
            // instead of clipping or pushing the title.
            <div className="flex flex-wrap items-center justify-center gap-x-2 gap-y-1 mt-1 text-[11px]" style={{ color: C.muted, lineHeight: 1.3 }}>
              {subtitle}
            </div>
          )}
        </div>
        <div className="w-10 flex justify-end">{renderAction(rightAction)}</div>
      </div>
    </header>
  );
};

const TabBar = ({ active, setActive }: {
  active: string;
  setActive: (tab: string) => void;
}) => {
  const tabs = [
    { id: "dashboard", label: "Home", icon: Home },
    // Settings is intentionally NOT a bottom-nav tab: it's pure config,
    // the least-frequently used surface, and already reachable from the
    // gear on the Home header (openSettings → secondary "settings"). The
    // `active === "studio"` render branch + deep links still work, so
    // anything that routes there keeps functioning — we only drop the
    // button so Checkout fits without crowding the bar.
    { id: "calculator", label: "Quote", icon: CalcIcon },
    { id: "schedule", label: "Schedule", icon: Calendar },
    { id: "clients", label: "Clients", icon: Users },
    { id: "checkout", label: "Checkout", icon: ShoppingBag },
    { id: "money", label: "Money", icon: TrendingUp },
  ];
  return (
    // Fixed to the viewport bottom (not sticky) so short pages like the
    // empty Client Photos tab don't float the nav up over content. Stays
    // centered inside the 480px shell on tablet / desktop. Z-index sits
    // below the sheet overlay (z-50) so modals always cover it.
    <nav
      className="bbp-tabbar fixed left-1/2 z-40 w-full max-w-[480px]"
      style={{
        bottom: 0,
        transform: "translateX(-50%)",
        background: `linear-gradient(180deg, ${C.cream} 0%, ${C.paper} 100%)`,
        borderTop: `1px solid ${C.hairline}`,
        paddingBottom: "env(safe-area-inset-bottom, 0px)",
        boxShadow: "0 -8px 24px -16px rgba(21, 17, 26, 0.18)",
      }}>
      <div className="flex items-center justify-around px-2 py-2">
        {tabs.map(t => {
          const Icon = t.icon;
          const isActive = active === t.id;
          return (
            <button
              type="button"
              key={t.id}
              onClick={() => setActive(t.id)}
              aria-current={isActive ? "page" : undefined}
              className="relative flex flex-col items-center gap-1 px-3 py-1.5 rounded-xl transition"
              // 2026 refresh: active tab now picks up the brand
              // gradient (purple → coral) on the icon stroke and
              // the indicator pill below the label.
              style={{
                color: isActive ? C.brandPrimary : C.brandMuted,
                minWidth: 60,
              }}
            >
              <Icon size={22} strokeWidth={isActive ? 2.4 : 1.85} />
              <span
                className="text-[10px] tracking-wide"
                style={{
                  fontWeight: isActive ? 700 : 600,
                  color: isActive ? C.brandText : C.brandMuted,
                  letterSpacing: "0.06em",
                }}
              >
                {t.label}
              </span>
              {isActive && (
                <span
                  aria-hidden
                  className="absolute"
                  style={{
                    bottom: 2,
                    left: "50%",
                    transform: "translateX(-50%)",
                    width: 18, height: 2.5,
                    borderRadius: 999,
                    background: GRADIENTS.primary,
                    boxShadow: "0 2px 6px -1px rgba(124, 58, 237, 0.4)",
                  }}
                />
              )}
            </button>
          );
        })}
      </div>
    </nav>
  );
};

const STATUS_TONE = { scheduled: "neutral", confirmed: "gold", completed: "success", cancelled: "danger", canceled: "danger", no_show: "warning" };
const STATUS_LABEL = { scheduled: "Scheduled", confirmed: "Confirmed", completed: "Completed", cancelled: "Cancelled", canceled: "Canceled", no_show: "No-show" };
const REMINDER_STATUS_TONE = { pending: "warning", sent: "gold", delivered: "success", failed: "danger", cancelled: "neutral" };

// ---- BOOKING SOURCE ATTRIBUTION ----------------------------------------
// "Where did this client find me?" Stored free-text on appointments
// (referral_source); these presets power the in-app chip picker and the
// Analytics "Where bookings come from" breakdown. Anything the stylist
// types is preserved — the labels map just prettifies the known keys.
const REFERRAL_SOURCE_PRESETS: Array<{ value: string; label: string }> = [
  { value: "instagram", label: "Instagram" },
  { value: "tiktok", label: "TikTok" },
  { value: "facebook", label: "Facebook" },
  { value: "google", label: "Google" },
  { value: "yelp", label: "Yelp" },
  { value: "referral", label: "Friend / referral" },
  { value: "returning_client", label: "Returning" },
  { value: "walk_in", label: "Walk-in" },
];
const REFERRAL_SOURCE_LABELS: Record<string, string> = {
  instagram: "Instagram", tiktok: "TikTok", facebook: "Facebook",
  google: "Google", yelp: "Yelp", referral: "Friend / referral",
  returning_client: "Returning", walk_in: "Walk-in",
  // Auto-stamped buckets — public booking links + waitlist conversions.
  direct_link: "Booking link", public_booking: "Booking link",
  waitlist: "Waitlist", manual: "Added manually", other: "Other",
};
// Normalize a free-text source into a stable key (lowercase, spaces→_).
const normalizeReferralSource = (raw: string | null | undefined): string =>
  (raw || "").trim().toLowerCase().replace(/\s+/g, "_");
const referralSourceLabel = (raw: string | null | undefined): string => {
  const k = normalizeReferralSource(raw);
  if (!k) return "Untagged";
  return REFERRAL_SOURCE_LABELS[k] || (raw as string);
};

// ============================================================
//  TIMER MINI PILL
// ============================================================
const TimerMiniPill = ({ timer, onClick }) => {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (timer?.status !== "running") return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [timer?.status]);
  if (!timer) return null;

  const elapsed = timer.status === "paused"
    ? new Date(timer.pausedAt).getTime() - new Date(timer.startedAt).getTime() - timer.totalPausedMs
    : now - new Date(timer.startedAt).getTime() - timer.totalPausedMs;

  return (
    <button type="button" onClick={onClick}
      className="fixed z-40 active:scale-[0.97] transition flex items-center gap-3 px-4 py-2.5 rounded-full"
      style={{
        bottom: 84, left: "50%", transform: "translateX(-50%)",
        background: `linear-gradient(135deg, ${C.espresso}, ${C.coffee})`,
        color: C.cream, border: `1.5px solid ${C.gold}`,
        boxShadow: "0 12px 32px -8px rgba(21, 17, 26, 0.45)",
        minWidth: 220,
      }}>
      <div className="rounded-full p-1.5" style={{ background: timer.status === "running" ? C.gold : C.mutedSoft, color: C.espresso }}>
        {timer.status === "running" ? <TimerIcon size={14} strokeWidth={2.5} /> : <Pause size={14} strokeWidth={2.5} />}
      </div>
      <div className="flex-1 text-left min-w-0">
        <p className="text-[10px] uppercase tracking-widest font-bold" style={{ color: C.gold, letterSpacing: "0.16em" }}>
          {timer.status === "running" ? "Timer running" : "Paused"}
        </p>
        <p className="text-sm font-mono font-semibold truncate" style={{ fontVariantNumeric: "tabular-nums" }}>
          {fmtDuration(Math.max(0, elapsed))} · {timer.clientName || timer.style || "Session"}
        </p>
      </div>
      <ChevronRight size={18} style={{ color: C.gold }} />
    </button>
  );
};
