// ---- Service picker (Phase 2) ----------------------------------------
// Shown above the Style/Service field on appointment forms. Picking a
// service prefills empty/zero fields only; "Replace with service
// defaults" overwrites everything catalog-driven for users who want
// the full reset behavior.
const ServicePicker = ({
  services, value, onPick,
}: {
  services: Service[];
  value: string | null;
  onPick: (svc: Service | null, mode: "fill" | "replace") => void;
}) => {
  const active = services.filter(s => s.is_active);
  const selected = value ? services.find(s => s.id === value) : null;
  // Surface inactive selected service so the user can keep / unbind.
  const opts = [
    { value: "", label: active.length === 0 ? "No services in catalog" : "— Pick a service —" },
    ...active.map(s => ({ value: s.id, label: `${s.name} · ${s.duration_hours}h` })),
  ];
  if (selected && !active.find(s => s.id === selected.id)) {
    opts.push({ value: selected.id, label: `${selected.name} · ${selected.duration_hours}h (inactive)` });
  }
  return (
    <Field label="Service" hint={active.length === 0 ? "Add services in Settings → Services & styles." : "Picks fill empty fields; manual edits stay."}>
      <Select
        value={value || ""}
        onChange={e => {
          const v = e.target.value;
          if (!v) { onPick(null, "fill"); return; }
          const svc = services.find(s => s.id === v) || null;
          onPick(svc, "fill");
        }}
        options={opts}
      />
      {selected && (
        <button
          type="button"
          onClick={() => onPick(selected, "replace")}
          className="text-[11px] font-semibold mt-1.5 px-1 py-0.5 active:scale-[0.98] transition"
          style={{ color: C.goldDeep, background: "transparent", border: 0 }}
        >
          Replace with service defaults
        </button>
      )}
    </Field>
  );
};

// No-show protection — shown in the appointment sheet when the status is
// No-show. Reads the card saved at deposit time (off the linked
// booking_request) and lets the stylist charge a configurable fee to it
// off-session, one tap. Charge goes through /api/no-show-charge.
const NoShowProtectionCard = ({
  store,
  appointmentId,
  servicePrice,
}: {
  store: any;
  appointmentId: string;
  servicePrice: number;
}) => {
  const currency = store?.business?.currency || "USD";
  const policy: BookingPolicy | null = store?.policiesApi?.policy || null;
  const [loading, setLoading] = useState(true);
  const [info, setInfo] = useState<{
    brand: string | null;
    last4: string | null;
    chargedAt: string | null;
    chargedAmount: number | null;
    consentAt: string | null;
  } | null>(null);
  const [amount, setAmount] = useState<string>("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  const suggested = computeNoShowFee(policy, servicePrice);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!appointmentId || !store?.userId) { setLoading(false); return; }
      try {
        const supabase = getSupabase();
        const { data } = await supabase
          .from("booking_requests")
          .select("nshow_card_brand, nshow_card_last4, no_show_fee_charged_at, no_show_fee_amount, no_show_consent_at")
          .eq("appointment_id", appointmentId)
          .eq("user_id", store.userId)
          .maybeSingle();
        if (cancelled) return;
        setInfo({
          brand: data?.nshow_card_brand ?? null,
          last4: data?.nshow_card_last4 ?? null,
          chargedAt: data?.no_show_fee_charged_at ?? null,
          chargedAmount: data?.no_show_fee_amount ?? null,
          consentAt: data?.no_show_consent_at ?? null,
        });
        if (suggested > 0) setAmount(String(suggested));
      } catch {
        if (!cancelled) setInfo(null);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appointmentId, store?.userId]);

  if (loading) return null;
  // No card on file → nothing to charge (deposit wasn't paid / pre-dates
  // the feature). Stay quiet rather than show a dead control.
  if (!info || !info.last4) return null;

  if (info.chargedAt) {
    return (
      <Card className="p-3.5" style={{ border: `1px solid ${C.hairline}` }}>
        <div className="flex items-center gap-2">
          <CheckCircle2 size={15} style={{ color: C.success }} />
          <p className="text-sm font-semibold" style={{ color: C.espresso }}>No-show fee charged</p>
        </div>
        <p className="text-[12px] mt-1" style={{ color: C.muted }}>
          {fmtMoney(Number(info.chargedAmount) || 0, currency)} charged to the card on file
          {info.last4 ? ` ···· ${info.last4}` : ""}.
        </p>
      </Card>
    );
  }

  const charge = async () => {
    const amt = parseMoney(amount);
    if (busy) return;
    if (!info?.consentAt) { setErr("This client didn't agree to a no-show fee at booking, so the card can't be charged."); return; }
    if (!(amt >= 1)) { setErr("Enter a fee of at least $1."); return; }
    setBusy(true); setErr(null); setDone(null);
    try {
      const supabase = getSupabase();
      const { data: sess } = await supabase.auth.getSession();
      const token = sess?.session?.access_token;
      if (!token) { setErr("Please sign in again."); setBusy(false); return; }
      const res = await fetch("/api/no-show-charge", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ access_token: token, appointment_id: appointmentId, amount_cents: Math.round(amt * 100) }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok || !json?.ok) {
        setErr(json?.error || "Couldn't charge the card.");
        setBusy(false);
        return;
      }
      setDone(`Charged ${fmtMoney(amt, currency)}.`);
      setInfo((prev) => prev ? { ...prev, chargedAt: new Date().toISOString(), chargedAmount: amt } : prev);
    } catch {
      setErr("Couldn't reach the server. Try again.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Card className="p-3.5 space-y-2.5" style={{ border: `1px solid ${C.hairline}` }}>
      <div>
        <p className="text-sm font-semibold" style={{ color: C.espresso }}>No-show protection</p>
        <p className="text-[11px]" style={{ color: C.muted, lineHeight: 1.4 }}>
          Card on file: {info.brand ? `${info.brand} ` : ""}···· {info.last4}.
          {suggested > 0
            ? ` Suggested fee ${fmtMoney(suggested, currency)} per your policy.`
            : " Set a default fee in Booking policies."}
        </p>
      </div>
      <p className="text-[11px]" style={{ color: info.consentAt ? C.success : C.danger, lineHeight: 1.4 }}>
        {info.consentAt
          ? `Client agreed to the no-show policy on ${fmtRelative(info.consentAt)}.`
          : "This client didn't agree to a no-show fee at booking, so the card can't be charged."}
      </p>
      <Field label="Fee to charge">
        <MoneyInput value={amount} onChange={(v) => setAmount(v)} />
      </Field>
      {err && <p className="text-[12px]" style={{ color: C.danger }}>{err}</p>}
      {done && <p className="text-[12px]" style={{ color: C.success }}>{done}</p>}
      <Button onClick={charge} disabled={busy || !info.consentAt} fullWidth icon={<DollarSign size={16} />}>
        {busy ? "Charging…" : "Charge no-show fee"}
      </Button>
    </Card>
  );
};

// Shown in the appointment sheet when a booking is cancelled — one tap
// to email the waitlist about the freed slot, pre-filled from the
// appointment's date/time/style.
const CancelledWaitlistNotify = ({
  store, date, time, style,
}: { store: any; date: string; time?: string | null; style?: string | null }) => {
  const requests: any[] = store?.waitlistApi?.requests || [];
  const reachable = requests.filter((r) => r?.client_email && (r.status === "waiting" || r.status === "contacted")).length;
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  if (reachable === 0) return null;

  const notify = async () => {
    if (busy || !store?.userId || !date) return;
    setBusy(true); setResult(null);
    const res = await broadcastWaitlistOpening(
      store.userId,
      { date, time: time || null, serviceName: style || null },
      requests,
    );
    setBusy(false);
    setResult(res.total === 0 ? "No waitlist clients have an email on file." : `Emailed ${res.sent} of ${res.total} waitlist client${res.total === 1 ? "" : "s"}.`);
  };

  return (
    <Card className="p-3.5" style={{ border: `1px solid ${C.hairline}` }}>
      <div className="flex items-center gap-2 mb-1">
        <Zap size={14} style={{ color: C.goldDeep }} />
        <p className="text-sm font-semibold" style={{ color: C.espresso }}>This slot just opened up</p>
      </div>
      <p className="text-[11px]" style={{ color: C.muted, lineHeight: 1.4 }}>
        Notify your {reachable} active waitlist client{reachable === 1 ? "" : "s"} so someone can grab it
        {date ? ` · ${date}${time ? ` at ${time}` : ""}` : ""}.
      </p>
      {result && <p className="text-[12px] mt-2" style={{ color: C.coffee }}>{result}</p>}
      <Button variant="outline" size="sm" onClick={notify} disabled={busy || !date} icon={<Send size={15} />} className="mt-2">
        {busy ? "Sending…" : "Notify waitlist"}
      </Button>
    </Card>
  );
};

// Compact appointment action row — coloured icon chip + title +
// subtitle, optional chevron — styled to match the "all from your
// chair" features-page menu we advertise. Keeps the full action set.
const ApptActionRow = ({
  icon, iconColor, chip, title, sub, onClick, chevron, danger, badge,
}: {
  icon: React.ReactNode; iconColor: string; chip: string;
  title: string; sub?: string; onClick: () => void;
  chevron?: boolean; danger?: boolean; badge?: React.ReactNode;
}) => (
  <button
    type="button"
    onClick={onClick}
    className="w-full flex items-center gap-3 px-2.5 py-2.5 rounded-xl active:scale-[0.99] transition text-left"
  >
    <span className="grid place-items-center shrink-0" style={{ width: 32, height: 32, borderRadius: 9, background: chip, color: iconColor }}>
      {icon}
    </span>
    <span className="flex-1 min-w-0">
      <span className="block font-semibold" style={{ fontSize: 13.5, color: danger ? C.danger : C.espresso }}>{title}</span>
      {sub && <span className="block truncate" style={{ fontSize: 11.5, color: C.muted }}>{sub}</span>}
    </span>
    {badge != null && badge !== false && badge !== "" && (
      <span className="shrink-0" style={{ fontSize: 11, fontWeight: 700, color: C.coffee, background: C.ivory, border: `1px solid ${C.hairline}`, borderRadius: 999, padding: "2px 8px" }}>
        {badge}
      </span>
    )}
    {chevron && <ChevronRight size={16} style={{ color: C.mutedSoft }} />}
  </button>
);

const AppointmentSheet = ({ open, appt, store, onClose, openTimerForAppt, openCommunication, openReceipt }: { open: any; appt: any; store: any; onClose: any; openTimerForAppt: any; openCommunication?: (ctx: CommContext) => void; openReceipt?: (rcp: ReceiptRecord) => void }) => {
  const {
    upsertAppointment, deleteAppointment, clients, upsertClient, business,
    recurringSeries, upsertSeries, deleteSeries, scheduleRemindersForAppointment,
    appointments, reminderSettings, receipts, upsertReceipt, deleteReceipt,
  } = store;
  const [form, setForm] = useState<EntityRecord>({});
  // Native shell vs web/PWA — drives the in-person payment copy and gates
  // the in-app Tap to Pay button. ttpSupported is the real on-device check
  // (native plugin present + device/entitlement capable); it stays false
  // on web/PWA and on native builds without the Tap to Pay plugin, so the
  // card falls back to the manual copy.
  const isNative = useIsNativePlatform();
  const [ttpSupported, setTtpSupported] = useState(false);
  const [ttpBusy, setTtpBusy] = useState(false);
  const [ttpMsg, setTtpMsg] = useState<{ kind: "ok" | "error"; text: string } | null>(null);
  // Reader configuration / charge progress (drives the status indicator)
  // and a latch that reveals the post-payment digital receipt options.
  const [ttpStatus, setTtpStatus] = useState<TapToPayStatus | null>(null);
  const [ttpPaid, setTtpPaid] = useState(false);
  useEffect(() => {
    if (!isNative) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- platform-driven sync, intentional
      setTtpSupported(false);
      return;
    }
    let alive = true;
    tapToPaySupported()
      .then((ok) => { if (alive) setTtpSupported(ok); })
      .catch(() => { if (alive) setTtpSupported(false); });
    return () => { alive = false; };
  }, [isNative]);
  const [showNewClient, setShowNewClient] = useState(false);
  const [newClientName, setNewClientName] = useState("");
  // After save, if the appointment was just transitioned to
  // "completed", show the MaterialsUsedSheet before closing so the
  // stylist can confirm what was consumed against the appointment.
  const [showMaterialsFor, setShowMaterialsFor] = useState<{ id: string; style?: string | null; recipe?: RecipeLine[] | null; addons?: any[] | null } | null>(null);

  // Recurring
  const [makeRecurring, setMakeRecurring] = useState(false);
  const [cadence, setCadence] = useState("4w");
  const [customDays, setCustomDays] = useState<string | number>(28);
  const [occurrences, setOccurrences] = useState<string | number>(6);

  // Reminders
  const [remindersEnabled, setRemindersEnabled] = useState(true);
  const [reminderChannel, setReminderChannel] = useState<EntityRecord | null>(null); // null = use default
  // SMS reminders — the stylist confirms the client agreed to texts
  // (consent source = "stylist"). Drives the SMS reminder + the SMS
  // confirmation; gated server-side on phone + credits + opt-out.
  const [smsOptIn, setSmsOptIn] = useState(false);
  // Whether to email the client about THIS booking / change. Defaults on,
  // but lets the stylist save quietly — e.g. fixing a mistake or creating
  // a placeholder — without spamming the client (a real pain when a
  // double-booking gets created then cancelled). Gates the booking
  // confirmation, the "appointment updated" notice, and (via the cancel
  // flow) the cancellation email.
  const [notifyClient, setNotifyClient] = useState(true);
  // Styled "Send notification" modal (replaces the native confirms). A
  // promise resolver lets the async save/cancel flows await the stylist's
  // choice. `allowMessage` shows the optional note (confirmation only).
  const [notifyPrompt, setNotifyPrompt] = useState<
    | { kind: "book" | "update" | "cancel"; who: string; smsToo: boolean; contractNote: string; allowMessage: boolean }
    | null
  >(null);
  const [notifyMessage, setNotifyMessage] = useState("");
  const notifyResolverRef = useRef<((r: { notify: boolean; message: string }) => void) | null>(null);
  const askNotify = (
    opts: { kind: "book" | "update" | "cancel"; who: string; smsToo: boolean; contractNote: string; allowMessage: boolean },
  ) => new Promise<{ notify: boolean; message: string }>((resolve) => {
    notifyResolverRef.current = resolve;
    setNotifyMessage("");
    setNotifyPrompt(opts);
  });
  const resolveNotify = (notify: boolean) => {
    const r = notifyResolverRef.current;
    notifyResolverRef.current = null;
    const msg = notifyMessage.trim();
    setNotifyPrompt(null);
    setNotifyMessage("");
    r?.({ notify, message: notify ? msg : "" });
  };

  // Custom (one-off) add-on draft. Committed to form.addons via the
  // "Add" button so the total/duration only move on an explicit action,
  // never mid-typing.
  const [customAddonName, setCustomAddonName] = useState("");
  const [customAddonPrice, setCustomAddonPrice] = useState("");
  const [customAddonHours, setCustomAddonHours] = useState("");

  useEffect(() => {
    if (open) {
      // CRITICAL: seed from the CANONICAL stored appointment, not the
      // prop. Several surfaces (deposit widgets, Boss Insights,
      // dashboard rows) open the sheet with a slim/synthesized
      // appointment object — seeding/saving from that would overwrite
      // the real total_price / deposit_paid / add-ons / customization
      // snapshot with partial data. Resolve the full record by id.
      const a = (appt?.id && Array.isArray(store?.appointments))
        ? (store.appointments.find((x: any) => x?.id === appt.id) || appt)
        : appt;
      const existingSeries = a?.seriesId ? recurringSeries.find(s => s.id === a.seriesId) : null;
      // eslint-disable-next-line react-hooks/set-state-in-effect -- prop/store-driven sync, intentional
      setForm({
        clientId: a?.clientId || "",
        clientName: a?.clientName || "",
        clientPhone: a?.clientPhone || "",
        clientEmail: a?.clientEmail || "",
        style: a?.style || "",
        date: a?.date || todayISO(),
        time: a?.time || "10:00",
        durationHours: a?.durationHours || "",
        depositPaid: sanitizeMoneyInput(a?.depositPaid ?? 0),
        totalPrice: sanitizeMoneyInput(a?.totalPrice ?? 0),
        status: a?.status || "scheduled",
        notes: a?.notes || "",
        paymentStatus: a?.paymentStatus || "",
        paymentDate: a?.paymentDate || "",
        paymentMethod: a?.paymentMethod || "",
        paymentNotes: a?.paymentNotes || "",
        // Discount snapshot — accept either camelCase (local) or
        // snake_case (cloud row) so both prefill cleanly. `discounts` is
        // the canonical list (multiple discounts stack); the legacy
        // discountId/discountName/discountAmount fields are kept in sync
        // for the promoted DB columns + anything that reads the single
        // total (receipts, reports). Records saved before stacking carry
        // only the legacy fields, so we migrate them into a 1-item list.
        discounts: (() => {
          const list = Array.isArray(a?.discounts) ? a.discounts : null;
          if (list && list.length > 0) {
            return list.map((d: any) => ({
              id: String(d?.id ?? ""),
              name: String(d?.name ?? ""),
              amount: sanitizeMoneyInput(d?.amount ?? 0),
            })).filter((d: AppliedDiscount) => d.id);
          }
          const legacyId = a?.discountId ?? a?.discount_id ?? null;
          if (legacyId) {
            return [{
              id: String(legacyId),
              name: String(a?.discountName ?? a?.discount_name ?? ""),
              amount: sanitizeMoneyInput(a?.discountAmount ?? a?.discount_amount ?? 0),
            }];
          }
          return [] as AppliedDiscount[];
        })(),
        discountId: a?.discountId ?? a?.discount_id ?? null,
        discountName: a?.discountName ?? a?.discount_name ?? null,
        discountAmount: sanitizeMoneyInput(a?.discountAmount ?? a?.discount_amount ?? 0),
        // Account credit applied to this appointment's balance. Rides in
        // the data jsonb; the canonical ledger is reconciled on save.
        creditApplied: sanitizeMoneyInput(a?.creditApplied ?? 0),
        // Phase 2: track which service catalog row this appointment
        // came from. Snapshot only — used for picker highlight + the
        // "Replace with service defaults" affordance.
        serviceId: a?.serviceId ?? a?.service_id ?? null,
        // Deposit-by-source. Defaults to false for manual creates so
        // the dashboard's "Deposit due" filter doesn't surface
        // appointments where no deposit was ever asked for. Existing
        // public-booking-link rows carry depositRequired=true from
        // approval and we honor whatever value the appt already has.
        depositRequired: a?.depositRequired ?? false,
        // Booking provenance. New manual appts land as "manual";
        // existing rows keep whatever was previously stamped.
        source: a?.source ?? (a?.id ? null : "manual"),
        // Referral attribution — "how did they find you?" Free-text in
        // the DB; the form drives it via the chip picker below.
        referralSource: a?.referralSource ?? a?.referral_source ?? "",
        // Calendar item kind. Default 'appointment' so existing rows
        // keep their pre-migration semantics. Personal events / blocked
        // time hide the client + payment sections in the form.
        kind: (a?.kind as ("appointment" | "personal" | "blocked") | undefined) || "appointment",
        // Free-text title used by personal events and blocked time
        // (e.g. "Doctor's appointment" / "Lunch with Mom"). Stored on
        // the same record; falls back to clientName for existing rows.
        eventTitle: a?.eventTitle || a?.event_title || "",
        // Add-ons snapshot — booking-flow extras the client picked, now
        // editable here so the stylist can correct what was selected
        // (e.g. add the "hair included" option after the fact). Each
        // entry: { id, name, price, duration_hours_delta,
        // include_in_deposit }. Spreading onto the canonical record at
        // save preserves anything else the snapshot carries.
        addons: Array.isArray(a?.addons) ? a.addons.map((x: any) => ({ ...x })) : [],
        // Service variation/option snapshot (the booking page's "Choose
        // an option" pick — e.g. Standard vs Boho Hair Included). Null
        // when the base service was booked. Editable below so a stylist
        // can switch the option for a client who booked the wrong one;
        // the switch re-prices the appointment.
        variationId: a?.variationId ?? a?.variation_id ?? null,
        variationName: a?.variationName ?? a?.variation_name ?? null,
        // Style customization snapshot — braiding-hair color, boho/curl
        // pattern, and style notes the client picked at booking. Cloned
        // so the editor below can change them without mutating the
        // canonical record; rides through the PATCH-style save.
        customization: (a?.customization && typeof a.customization === "object")
          ? { ...a.customization, summary: { ...(a.customization.summary || {}) } }
          : {},
        // Family member this appointment is for (kids/dependents). The
        // client (clientId) stays the contact + payer; this is just who
        // the style is for. Null when the appointment is for the client
        // themselves. Rides through the save in the data jsonb.
        dependentId: a?.dependentId ?? null,
        dependentName: a?.dependentName ?? null,
        id: a?.id,
        seriesId: a?.seriesId,
        // Hair recipe carried from the pricing calculator. Rides through
        // the PATCH-style save and pre-fills the Materials-used sheet when
        // the appointment is marked completed.
        recipe: Array.isArray(a?.recipe) ? a.recipe.map((l: any) => ({ ...l })) : [],
      });
      setCustomAddonName("");
      setCustomAddonPrice("");
      setCustomAddonHours("");
      setShowNewClient(false);
      setNewClientName("");
      setMakeRecurring(!!existingSeries);
      setCadence(existingSeries?.cadence || "4w");
      setCustomDays(existingSeries?.customIntervalDays || 28);
      setOccurrences(existingSeries?.occurrencesPlanned || 6);
      setRemindersEnabled(a?.remindersEnabled !== false);
      setReminderChannel(a?.reminderChannel || null);
      setSmsOptIn(!!a?.smsOptIn);
      setNotifyClient(true);
    }
    // store.appointments intentionally NOT a dep — seed once per open;
    // re-seeding mid-edit would discard the stylist's in-progress edits.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, appt]);

  // Discount picker (V1: only "applies to all" discounts surface).
  const allDiscounts: Discount[] = store.discountsApi?.discounts || [];
  const discountUsage = useMemo(
    () => discountUsageFromAppointments(store.appointments),
    [store.appointments],
  );
  const availableDiscounts = useMemo(
    () => selectableDiscounts(allDiscounts, Date.now(), discountUsage),
    [allDiscounts, discountUsage],
  );
  // The discounts already applied to this appointment.
  const appliedDiscounts: AppliedDiscount[] = useMemo(
    () => (Array.isArray(form.discounts) ? form.discounts : []),
    [form.discounts],
  );
  // Discounts the stylist can still add: selectable, not already applied.
  const addableDiscounts = useMemo(
    () => availableDiscounts.filter(d => !appliedDiscounts.some(a => a.id === d.id)),
    [availableDiscounts, appliedDiscounts],
  );
  // Recompute every applied discount's dollar amount against the current
  // price. Discounts stack: each is figured off the gross price, but the
  // running remainder is capped so the combined total can't exceed it.
  // An applied discount whose definition was deleted/paused keeps its
  // recorded amount (still capped) so historical records don't re-price.
  const recomputeAppliedDiscounts = useCallback(
    (list: AppliedDiscount[], total: number): AppliedDiscount[] => {
      let remaining = Math.max(0, Number(total) || 0);
      return list.map(item => {
        const def = allDiscounts.find(d => d.id === item.id);
        const raw = def
          ? computeDiscountAmount(Number(total) || 0, def)
          : Number(item.amount) || 0;
        const amount = Number(Math.min(raw, remaining).toFixed(2));
        remaining = Number((remaining - amount).toFixed(2));
        return { id: item.id, name: def?.name ?? item.name, amount };
      });
    },
    [allDiscounts],
  );

  // Phase 2 — apply a service to the form. mode = "fill" only writes
  // empty/zero fields (default behavior so the user's manual edits
  // are never silently overwritten); mode = "replace" overwrites
  // every catalog-driven field. Service id is stored either way as a
  // soft snapshot.
  const applyServiceToForm = (svc: Service | null, mode: "fill" | "replace") => {
    if (!svc) {
      setForm({ ...form, serviceId: null });
      return;
    }
    const overwriteEmpty = (current: any, next: any) =>
      mode === "replace" ? next : (current && current !== "" && current !== 0 ? current : next);
    const dur = Number(svc.duration_hours) || 0;
    setForm(prev => ({
      ...prev,
      serviceId: svc.id,
      style: overwriteEmpty(prev.style, svc.name),
      durationHours: overwriteEmpty(Number(prev.durationHours) || 0, dur) || prev.durationHours,
      totalPrice: overwriteEmpty(Number(prev.totalPrice) || 0, svc.base_price) || prev.totalPrice,
      depositPaid: prev.depositPaid, // never auto-pay on the user's behalf
      // Surface deposit_amount in the notes/prep area only — the
      // appointment's own depositPaid field reflects what the
      // STYLIST has actually collected, not the required amount.
      notes: mode === "replace" || !prev.notes
        ? (svc.prep_instructions ? `${svc.prep_instructions}${prev.notes ? `\n\n${prev.notes}` : ""}` : prev.notes)
        : prev.notes,
    }));
  };

  const addDiscount = (id: string) => {
    if (!id) return;
    if (appliedDiscounts.some(d => d.id === id)) return;
    const d = availableDiscounts.find(x => x.id === id);
    if (!d) return;
    setForm(prev => ({
      ...prev,
      discounts: [...(prev.discounts || []), { id: d.id, name: d.name, amount: 0 }],
    }));
  };

  const removeDiscount = (id: string) => {
    setForm(prev => ({
      ...prev,
      discounts: (prev.discounts || []).filter((d: AppliedDiscount) => d.id !== id),
    }));
  };

  // Keep the applied-discount amounts (and the legacy single-discount
  // mirror fields) in sync whenever the discount list, the entered total,
  // or the loaded discount definitions change. The mirror keeps the
  // promoted DB columns + receipts/reports working off one combined total:
  //   discountAmount = sum, discountId = first, discountName = "A + B".
  useEffect(() => {
    const total = Number(form.totalPrice) || 0;
    const next = recomputeAppliedDiscounts(appliedDiscounts, total);
    const sum = Number(next.reduce((s, d) => s + d.amount, 0).toFixed(2));
    const combinedName = next.map(d => d.name).filter(Boolean).join(" + ") || null;
    const firstId = next[0]?.id ?? null;
    const listChanged =
      next.length !== appliedDiscounts.length ||
      next.some((d, i) => {
        const cur = appliedDiscounts[i];
        return !cur || cur.amount !== d.amount || cur.name !== d.name;
      });
    if (
      listChanged ||
      Number(form.discountAmount) !== sum ||
      (form.discountId ?? null) !== firstId ||
      (form.discountName ?? null) !== combinedName
    ) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- derived re-quote of discount amounts, guarded against loops
      setForm(prev => ({
        ...prev,
        discounts: next,
        discountAmount: sum,
        discountId: firstId,
        discountName: combinedName,
      }));
    }
    // Mirror fields (discountAmount/Id/Name) are written here, not read as
    // triggers — including them would loop. The guard above is the loop break.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.totalPrice, appliedDiscounts, recomputeAppliedDiscounts]);

  // Account credit on the selected client. Applied to the BALANCE (never
  // the deposit) of this appointment. The ledger is canonical; we mirror
  // the applied amount onto the appointment for the math + receipts.
  const [creditEntries, setCreditEntries] = useState<CreditEntry[]>([]);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const uid_ = store.userId;
      if (!uid_ || !form.clientId) { if (!cancelled) setCreditEntries([]); return; }
      try {
        const list = await listCreditsForClient(uid_, form.clientId);
        if (!cancelled) setCreditEntries(list);
      } catch { if (!cancelled) setCreditEntries([]); }
    })();
    return () => { cancelled = true; };
  }, [store.userId, form.clientId, form.id]);

  const discountAmt = Number(form.discountAmount) || 0;
  const grossTotal = Number(form.totalPrice) || 0;
  const netTotal = Math.max(0, grossTotal - discountAmt);
  const balanceBeforeCredit = Math.max(0, netTotal - (Number(form.depositPaid) || 0));

  // Net credit currently on the account already nets out this
  // appointment's existing redemption, so add that back to get the pool
  // this appointment can actually draw from (mirrors the apply RPC).
  const clientCreditNet = creditBalance(creditEntries);
  const thisApptRedeemed = useMemo(() => {
    if (!form.id) return 0;
    let s = 0;
    for (const e of creditEntries) {
      if (e.kind === "redeem" && e.appointment_id === form.id) s += -Number(e.amount);
    }
    return Math.round(s * 100) / 100;
  }, [creditEntries, form.id]);
  const creditPool = Math.max(0, Math.round((clientCreditNet + thisApptRedeemed) * 100) / 100);
  const maxCreditApplicable = Math.min(creditPool, balanceBeforeCredit);
  // Effective applied credit is always clamped to what's actually
  // available + owed, so a later total/deposit change can never over-
  // apply. handleSave persists THIS value (not the raw form field).
  const creditApplied = Math.max(0, Math.min(Number(form.creditApplied) || 0, maxCreditApplicable));
  const balanceDue = Math.max(0, roundCents(balanceBeforeCredit - creditApplied));

  // When picking an existing client, auto-fill phone/email + their
  // most recent style/duration on NEW appointments only. We don't
  // overwrite anything the user already typed.
  useEffect(() => {
    if (form.clientId) {
      const c = clients.find(x => x.id === form.clientId);
      if (c) {
        const last = !form.id
          ? lastBookingForClient(appointments as any[], form.clientId)
          : null;
        // eslint-disable-next-line react-hooks/set-state-in-effect -- prop/store-driven sync, intentional
        setForm(prev => ({
          ...prev,
          clientName: c.name,
          clientPhone: prev.clientPhone || c.phone || "",
          clientEmail: prev.clientEmail || c.email || "",
          style: prev.style || (last?.style ?? ""),
          durationHours: prev.durationHours || last?.durationHours || "",
        }));
      }
    }
  }, [form.clientId, clients, form.id, appointments]);

  const handleSave = async () => {
    // Personal events and blocked time skip the entire client/payment/
    // recurring/reminders pipeline — they're just titled time-blocks.
    if (form.kind === "personal" || form.kind === "blocked") {
      const baseEvent = {
        ...form,
        // Wipe fields that don't apply so a kind-changed record stays clean.
        clientId: "", clientName: "",
        clientPhone: "", clientEmail: "",
        style: "",
        depositPaid: 0, totalPrice: 0,
        discounts: [], discountId: null, discountName: null, discountAmount: 0,
        paymentStatus: "", paymentDate: "", paymentMethod: "", paymentNotes: "",
        seriesId: undefined,
        remindersEnabled: false,
        reminderChannel: null,
      };
      const saved = await upsertAppointment(baseEvent);
      if (!saved) return;
      onClose();
      return;
    }

    let clientId = form.clientId;
    let clientName = form.clientName;
    if (showNewClient && newClientName.trim()) {
      const newC = await upsertClient({ name: newClientName.trim(), phone: form.clientPhone, email: form.clientEmail });
      if (!newC) return; // Gated by upgrade sheet — bail without saving the appointment.
      clientId = newC.id; clientName = newC.name;
    } else if (clientId) {
      const c = clients.find(x => x.id === clientId);
      if (c) clientName = c.name;
    }

    let seriesId = form.seriesId;
    let isFirstInNewSeries = false;

    // Create series if requested and not already in one
    if (makeRecurring && !seriesId) {
      const newSeries = await upsertSeries({
        clientId, style: form.style, cadence,
        customIntervalDays: cadence === "custom" ? Number(customDays) : null,
        totalPrice: Number(form.totalPrice) || 0,
        durationHours: Number(form.durationHours) || 0,
        occurrencesPlanned: Number(occurrences) || 6,
        occurrencesGenerated: 1,
        startDate: form.date, startTime: form.time,
        reminderEnabled: remindersEnabled,
        notes: form.notes || "",
        status: "active",
      });
      seriesId = newSeries.id;
      isFirstInNewSeries = true;
    } else if (!makeRecurring && seriesId) {
      // Removed recurrence — leave the parent series intact, just drop link
      seriesId = undefined;
    }

    // Guard: when a deposit was entered but no payment date is set,
    // stamp today. Without this the dashboard "Deposits (week)" KPI
    // and the per-appointment receipt PDF both miss the payment
    // (their filters require paymentDate). Only fills the gap — if
    // the stylist already chose a date in the form we leave it.
    const depositEntered = parseMoney(form.depositPaid) > 0;
    const paymentDateAutoFill = depositEntered && !form.paymentDate ? todayISO() : form.paymentDate;
    // PATCH semantics — never rebuild the appointment from just the
    // form. The form is a whitelisted subset (scheduling + payment +
    // discount); booking-created appointments also carry a snapshot
    // the form never surfaces: selected add-ons, style customization,
    // service variation, booking_request_id, Stripe payment-intent /
    // balance-token / review-token ids, deposit disposition, etc.
    // Spreading the original record FIRST preserves all of that; the
    // form then overlays only the fields the stylist actually edited.
    // For brand-new manual creates `appt` is null/empty, so this is a
    // no-op there and manual editing is unchanged.
    // Resolve the CANONICAL stored record by id (the sheet may have
    // been opened from a slim/synthesized appt object). Merging onto
    // the full record — never the partial prop — is what guarantees
    // add-ons / customization / Stripe + balance-token snapshot and
    // the true total_price / deposit_paid survive an edit.
    const canonical = (form.id && Array.isArray(store?.appointments))
      ? store.appointments.find((x: any) => x?.id === form.id)
      : null;
    const original =
      (canonical && typeof canonical === "object") ? canonical
      : (appt && typeof appt === "object") ? appt
      : {};
    const baseAppt = {
      ...original,
      ...form,
      // Persist the CLAMPED applied credit, never the raw form field —
      // a later total/deposit edit could leave form.creditApplied above
      // what's available/owed, and the balance math keys off this value.
      creditApplied,
      paymentDate: paymentDateAutoFill,
      clientId, clientName,
      seriesId,
      remindersEnabled,
      reminderChannel,
      smsOptIn,
      isRecurringInstance: !!seriesId,
      recurrenceIndex: form.recurrenceIndex ?? (isFirstInNewSeries ? 0 : form.recurrenceIndex),
    };

    const saved = await upsertAppointment(baseAppt);
    if (!saved) return; // Gated by upgrade sheet.

    // Reconcile account credit applied to this appointment's balance.
    // Idempotent: writes/clears the single redeem row for this appt and,
    // if the RPC capped the amount (insufficient balance), corrects the
    // stored creditApplied so the balance matches the ledger. Best-effort.
    try {
      const isRealAppt = (form.kind || "appointment") === "appointment";
      const notCancelled =
        (saved.status || "") !== "cancelled" && (saved.status || "") !== "canceled";
      if (isRealAppt && notCancelled && saved?.id && clientId &&
          (creditApplied > 0 || thisApptRedeemed > 0)) {
        const res = await applyCreditToAppointment(clientId, saved.id, creditApplied);
        if (Math.abs(res.applied - creditApplied) > 0.001) {
          await upsertAppointment({ ...saved, creditApplied: res.applied });
        }
      }
    } catch (e) {
      // Credit reconciliation is best-effort — never block the save.
      if (typeof console !== "undefined") console.warn("[appt] credit reconcile failed:", e);
    }

    // Track repeat bookings for the smart-studio funnel — fires when
    // the booked client already has a prior completed visit.
    if (saved?.clientId) {
      const hasPrior = (store.appointments || []).some((a: any) =>
        a && a.clientId === saved.clientId && a.id !== saved.id &&
        (a.status === "completed" || a.paymentStatus === "paid"),
      );
      if (hasPrior) trackEvent("repeat_booking_created", { category: "feature" });
    }
    await scheduleRemindersForAppointment({
      ...saved,
      remindersEnabled,
      clientPhone: form.clientPhone, clientEmail: form.clientEmail,
    });

    // New-appointment confirmation — email + (when the client opted
    // in) SMS. Whoever creates the appointment, the client gets a
    // confirmation. enqueue_appointment_confirmation handles the
    // per-channel gating (phone / credits / STOP opt-out) and dedupe;
    // best-effort, never blocks the save. Data is passed in so it
    // can't race the offline appointment sync.
    try {
      const isNew = !appt?.id;
      const isRealAppt = (form.kind || "appointment") === "appointment";
      const notCancelled =
        (saved.status || "") !== "cancelled" && (saved.status || "") !== "canceled";
      if (isNew && isRealAppt && notCancelled && notifyClient && store.userId) {
        // Ask before notifying so an accidental / placeholder booking
        // never emails the client by surprise. (The "Notify client"
        // toggle being off skips this entirely.)
        const who = form.clientName || saved.clientName || "the client";
        const hasEmail = (form.clientEmail || saved.clientEmail || "").trim();
        const hasSms = !!smsOptIn && (form.clientPhone || saved.clientPhone || "").trim();
        const contractNote = apptContractNames.length > 0 && hasEmail
          ? `They'll also get the ${apptContractNames.length === 1 ? "contract" : "contracts"} to sign.`
          : "";
        const choice = (hasEmail || hasSms)
          ? await askNotify({ kind: "book", who, smsToo: !!hasSms, contractNote, allowMessage: !!hasEmail })
          : { notify: false, message: "" };
        const okToNotify = choice.notify;
        if (okToNotify) {
          const balance = Number(saved.totalPrice ?? form.totalPrice ?? 0);
          await getSupabase().rpc("enqueue_appointment_confirmation", {
            appt_id_in: saved.id,
            user_id_in: store.userId,
            client_name_in: form.clientName || saved.clientName || null,
            client_email_in: (form.clientEmail || saved.clientEmail || "").trim() || null,
            client_phone_in: (form.clientPhone || saved.clientPhone || "").trim() || null,
            service_name_in: form.style || saved.style || null,
            appt_date_in: form.date || saved.date || null,
            appt_time_in: form.time || saved.time || null,
            total_price_in: Number.isFinite(balance) && balance > 0 ? balance : null,
            sms_opt_in_in: !!smsOptIn,
            custom_message_in: choice.message || null,
          });

          // Auto-send the service's contract(s) for this manual booking —
          // the online-booking approval flow already does this; manual
          // creates didn't, so the contract never reached the client.
          // Best-effort + idempotent (one row per appointment+template).
          if (hasEmail) {
            try {
              const supabase = getSupabase();
              await supabase.rpc("generate_appointment_contracts", { appointment_id_in: saved.id });
              const { data: bcs } = await supabase
                .from("booking_contracts")
                .select("id, title, public_token, status, client_email")
                .eq("appointment_id", saved.id)
                .is("signed_at", null)
                .in("status", ["sent", "pending", "pending_signature", "viewed"]);
              const list = (bcs as any[]) || [];
              if (list.length > 0) {
                let studioName = "your stylist";
                try {
                  const { data: studio } = await supabase.rpc("public_get_studio_name", { user_id_in: store.userId });
                  if (typeof studio === "string" && studio.trim()) studioName = studio.trim();
                } catch { /* studio name best-effort */ }
                const origin = typeof window !== "undefined" ? window.location.origin : "https://braidbosspro.app";
                for (const bc of list) {
                  if (!bc?.public_token) continue;
                  const email = String(bc.client_email || form.clientEmail || saved.clientEmail || "").trim();
                  if (!email) continue;
                  await supabase.rpc("queue_notification", {
                    user_id_in: store.userId,
                    channel_in: "email",
                    notification_type_in: "contract_signing",
                    body_in: "Please review and sign your appointment agreement.",
                    recipient_email_in: email,
                    recipient_name_in: form.clientName || saved.clientName || null,
                    payload_in: {
                      clientName: form.clientName || saved.clientName || "there",
                      studioName,
                      contractTitle: bc.title || "Appointment agreement",
                      serviceName: form.style || saved.style || null,
                      contractUrl: `${origin}/sign/contract/${bc.public_token}`,
                    },
                    dedupe_key_in: `contract_signing:${bc.id}`,
                    appointment_id_in: saved.id,
                    client_id_in: saved.clientId || form.clientId || null,
                  });
                }
              }
            } catch (e) {
              if (typeof console !== "undefined") console.warn("[appt] contract auto-send failed:", e);
            }
          }
        }
      }
    } catch {
      // Confirmation is best-effort — never block the save.
    }

    // Stylist-initiated change notice. When the stylist edits an
    // EXISTING real appointment and anything client-relevant moved —
    // date, time, total price, or add-ons — email the client ONE
    // consolidated "appointment updated" notice covering everything
    // that changed (rather than a separate email per field). Best-effort
    // + idempotent: the dedupe key carries the new slot + price + add-on
    // signature, so re-saving unchanged data won't resend, while any
    // further change produces a new key and a fresh email. Skipped for
    // brand-new creates, personal/blocked holds, cancelled rows, and
    // when there's no client email.
    try {
      const wasExisting = !!appt?.id;
      const isRealAppt = (form.kind || "appointment") === "appointment";
      const clientEmail = (form.clientEmail || saved.clientEmail || "").trim();
      const notCancelled = (saved.status || "") !== "cancelled" && (saved.status || "") !== "canceled";

      // Old values come from the canonical pre-edit record (`original`),
      // not the possibly-slim `appt` prop, so a sheet opened from a
      // synthesized object can't misreport what changed.
      const oldDate = (original as any)?.date || "";
      const oldTime = (original as any)?.time || "";
      const newDate = form.date || "";
      const newTime = form.time || "";
      const oldPrice = parseMoney((original as any)?.totalPrice);
      const newPrice = parseMoney(saved.totalPrice ?? form.totalPrice);
      // Stable signature of an add-on set (order-independent) so a
      // reorder isn't mistaken for a change but a price/qty edit is.
      const addonSig = (list: any): string =>
        (Array.isArray(list) ? list : [])
          .map((a: any) => `${a?.id ?? a?.name ?? ""}:${Number(a?.price) || 0}:${Number(a?.duration_hours_delta) || 0}`)
          .sort()
          .join("|");
      const oldAddons = Array.isArray((original as any)?.addons) ? (original as any).addons : [];
      const newAddons = Array.isArray(saved.addons)
        ? saved.addons
        : (Array.isArray(form.addons) ? form.addons : []);
      // Service option (variation). Compared by id so a relabeled
      // option still counts as the same pick.
      const oldVariationId = (original as any)?.variationId ?? (original as any)?.variation_id ?? null;
      const newVariationId = saved.variationId ?? form.variationId ?? null;
      const newVariationName = saved.variationName ?? form.variationName ?? null;
      const newServiceName = form.style || saved.style || null;
      // Style customization (braiding-hair color / boho curl / notes).
      // Same read precedence as the editor + display.
      const custFields = (c: any) => {
        const o = (c && typeof c === "object") ? c : {};
        const s = (o.summary && typeof o.summary === "object") ? o.summary : {};
        return {
          hairColor: String(o.hairColor ?? s.custom_hair_color ?? "").trim(),
          curlPattern: String(o.curlPattern ?? s.custom_curl_pattern ?? "").trim(),
          styleNotes: String(o.styleNotes ?? s.notes ?? "").trim(),
        };
      };
      const oldCust = custFields((original as any)?.customization);
      const newCust = custFields(saved.customization ?? form.customization);

      const changedDate = wasExisting && oldDate !== newDate;
      const changedTime = wasExisting && oldTime !== newTime;
      const changedPrice = wasExisting && Math.abs(oldPrice - newPrice) > 0.005;
      const changedAddons = wasExisting && addonSig(oldAddons) !== addonSig(newAddons);
      const changedOption = wasExisting && String(oldVariationId ?? "") !== String(newVariationId ?? "");
      const changedHairColor = wasExisting && oldCust.hairColor !== newCust.hairColor;
      const changedCurl = wasExisting && oldCust.curlPattern !== newCust.curlPattern;
      const changedNotes = wasExisting && oldCust.styleNotes !== newCust.styleNotes;
      const changedCustomization = changedHairColor || changedCurl || changedNotes;
      const oldStyle = String((original as any)?.style ?? "").trim();
      const changedStyle = wasExisting && oldStyle !== String(newServiceName ?? "").trim();
      const dateOrTimeChanged = changedDate || changedTime;
      const anyChanged = dateOrTimeChanged || changedPrice || changedAddons || changedOption || changedCustomization || changedStyle;

      // Keep the linked booking_request in sync with the edit. The
      // client portal (public_get_booking_portal_state) and the
      // worker's email enrichment both read schedule, price, and
      // add-ons straight off booking_requests, so an edit that only
      // touched the appointment row left "View appointment details"
      // showing the OLD time / price / add-ons. Sync whenever anything
      // relevant moved — independent of whether an email goes out.
      if (wasExisting && isRealAppt && anyChanged && notCancelled && store.userId) {
        try {
          await getSupabase().rpc("sync_booking_request_after_edit", {
            appointment_id_in: saved.id,
            new_date: newDate || null,
            new_time: newTime || null,
            // null leaves the stored ticket price intact (avoids
            // zeroing a row when the total isn't a positive number).
            new_total_price: (Number.isFinite(newPrice) && newPrice > 0) ? newPrice : null,
            // Pass the current add-on set (may be empty when removed)
            // so the portal reflects exactly what's booked now.
            new_addons: newAddons,
            // Service option (variation). The portal reads
            // coalesce(selected_variation_name, service_name); sync both
            // the variation id/name and the composed service name so
            // "View appointment details" shows the switched option.
            // Gated by update_option so an unrelated edit (e.g. just the
            // date) never rewrites the option/service name.
            new_variation_id: newVariationId,
            new_variation_name: newVariationName,
            new_service_name: newServiceName,
            update_option: changedOption,
            // Style customization — the portal reads selected_hair_color
            // / selected_curl_pattern / client_style_notes directly, so
            // sync them. Gated by update_customization so an unrelated
            // edit never overwrites them with a thin snapshot.
            new_hair_color: newCust.hairColor || null,
            new_curl_pattern: newCust.curlPattern || null,
            new_style_notes: newCust.styleNotes || null,
            update_customization: changedCustomization,
          });
        } catch { /* portal sync is best-effort */ }
      }

      // Style swapped on an existing appointment — the original contract
      // (if any) was for a different service, so void anything unsigned
      // and reissue against the new service so the client signs for what
      // they're actually booked into.
      if (wasExisting && isRealAppt && changedStyle && notCancelled && store.userId) {
        try {
          const supabase = getSupabase();
          await supabase
            .from("booking_contracts")
            .update({ status: "voided" })
            .eq("appointment_id", saved.id)
            .is("signed_at", null)
            .in("status", ["sent", "pending", "pending_signature", "viewed"]);
          await supabase.rpc("generate_appointment_contracts", { appointment_id_in: saved.id });
          if (clientEmail) {
            const { data: bcs } = await supabase
              .from("booking_contracts")
              .select("id, title, public_token, status, client_email")
              .eq("appointment_id", saved.id)
              .is("signed_at", null)
              .in("status", ["sent", "pending", "pending_signature", "viewed"]);
            const list = (bcs as any[]) || [];
            if (list.length > 0) {
              let studioName = "your stylist";
              try {
                const { data: studio } = await supabase.rpc("public_get_studio_name", { user_id_in: store.userId });
                if (typeof studio === "string" && studio.trim()) studioName = studio.trim();
              } catch { /* studio name best-effort */ }
              const origin = typeof window !== "undefined" ? window.location.origin : "https://braidbosspro.app";
              for (const bc of list) {
                if (!bc?.public_token) continue;
                const email = String(bc.client_email || clientEmail).trim();
                if (!email) continue;
                await supabase.rpc("queue_notification", {
                  user_id_in: store.userId,
                  channel_in: "email",
                  notification_type_in: "contract_signing",
                  body_in: "Please review and sign your updated appointment agreement.",
                  recipient_email_in: email,
                  recipient_name_in: form.clientName || saved.clientName || null,
                  payload_in: {
                    clientName: form.clientName || saved.clientName || "there",
                    studioName,
                    contractTitle: bc.title || "Appointment agreement",
                    serviceName: newServiceName,
                    contractUrl: `${origin}/sign/contract/${bc.public_token}`,
                  },
                  dedupe_key_in: `contract_signing:${bc.id}`,
                  appointment_id_in: saved.id,
                  client_id_in: saved.clientId || form.clientId || null,
                });
              }
            }
          }
        } catch (e) {
          if (typeof console !== "undefined") console.warn("[appt] contract reissue on style change failed:", e);
        }
      }

      const updateGate = wasExisting && isRealAppt && anyChanged && notCancelled &&
        notifyClient && clientEmail && store.userId;
      const updateNotify = updateGate
        ? (await askNotify({ kind: "update", who: form.clientName || saved.clientName || "the client", smsToo: false, contractNote: "", allowMessage: false })).notify
        : false;
      if (updateNotify) {
        const supabase = getSupabase();
        let studioName = "your stylist";
        try {
          const { data: studio } = await supabase
            .rpc("public_get_studio_name", { user_id_in: store.userId });
          if (typeof studio === "string" && studio.trim()) studioName = studio.trim();
        } catch { /* studio name best-effort */ }
        const currentAddonNames = (newAddons as any[])
          .map((a: any) => String(a?.name ?? "").trim())
          .filter(Boolean);
        await supabase.rpc("queue_notification", {
          user_id_in: store.userId,
          channel_in: "email",
          notification_type_in: "appointment_updated",
          body_in: "Your appointment details were updated.",
          subject_in: `Your appointment with ${studioName} was updated`,
          recipient_email_in: clientEmail,
          recipient_name_in: form.clientName || saved.clientName || null,
          payload_in: {
            clientName: form.clientName || saved.clientName || "there",
            studioName,
            serviceName: form.style || saved.style || null,
            // Per-category flags drive which "what changed" lines show.
            changedDate,
            changedTime,
            changedPrice,
            changedAddons,
            changedOption,
            changedHairColor,
            changedCurl,
            // New option label, when the option was switched.
            optionName: changedOption ? (newVariationName || "Standard") : null,
            // New customization values, when changed (notes stay out of
            // the client email — they can be long / internal).
            hairColor: changedHairColor ? (newCust.hairColor || "—") : null,
            curlPattern: changedCurl ? (newCust.curlPattern || "—") : null,
            // Old values only when that category actually moved.
            fromDate: changedDate ? (oldDate || null) : null,
            fromTime: changedTime ? (oldTime || null) : null,
            fromPrice: changedPrice ? oldPrice : null,
            // Current state — always reflects the new booking.
            preferredDate: newDate || null,
            preferredTime: newTime || null,
            totalPrice: Number.isFinite(newPrice) ? newPrice : null,
            currency: business?.currency || "USD",
            // Edited add-ons aren't synced to booking_requests, so pass
            // the current names explicitly rather than relying on the
            // worker's (stale) customization enrichment.
            currentAddonNames,
            // Lets the worker build the portal + cancel links against
            // this deployment's origin (it resolves the tokens from the
            // linked booking request).
            appBase: typeof window !== "undefined" ? window.location.origin : null,
          },
          dedupe_key_in: `appt_updated:${saved.id}:${newDate || "nodate"}:${newTime || "notime"}:${Math.round(newPrice * 100)}:${addonSig(newAddons)}:${newVariationId ?? "novar"}:${newCust.hairColor || "-"}:${newCust.curlPattern || "-"}`,
          appointment_id_in: saved.id,
        });
      }
    } catch {
      // Email is best-effort — never block the save on it.
    }

    // Generate future occurrences for new series
    if (isFirstInNewSeries) {
      const days = cadenceDays(cadence, Number(customDays));
      let nextDate = form.date;
      for (let i = 1; i < Number(occurrences); i++) {
        nextDate = addDaysISO(nextDate, days);
        const future = await upsertAppointment({
          clientId, clientName,
          clientPhone: form.clientPhone, clientEmail: form.clientEmail,
          style: form.style,
          date: nextDate, time: form.time,
          durationHours: form.durationHours,
          depositPaid: 0,
          totalPrice: form.totalPrice,
          status: "scheduled",
          notes: form.notes,
          seriesId,
          remindersEnabled,
          isRecurringInstance: true,
          recurrenceIndex: i,
        });
        if (!future) break; // Gated mid-series — stop generating.
        await scheduleRemindersForAppointment({
          ...future, remindersEnabled,
          clientPhone: form.clientPhone, clientEmail: form.clientEmail,
        });
      }
      // Update series count
      await upsertSeries({
        id: seriesId,
        ...recurringSeries.find(s => s.id === seriesId),
        occurrencesGenerated: Number(occurrences),
      });
    }

    // Inventory wire-up. When the stylist marks an appointment
    // completed for the first time, open the MaterialsUsedSheet so
    // they can confirm what was consumed against this appointment
    // (pre-filled from the service's default_materials). Only fires
    // for real appointments (not personal/blocked) — those returned
    // early above. Skipped if the user has no inventory yet, since
    // there's nothing to deduct against.
    const wasCompleted = (original as any)?.status === "completed";
    const nowCompleted = (saved as any)?.status === "completed";
    const inventoryReady = Array.isArray(store?.inventoryItems) && store.inventoryItems.length > 0;
    if (!wasCompleted && nowCompleted && inventoryReady) {
      setShowMaterialsFor({
        id: saved.id,
        style: saved.style ?? form.style ?? null,
        recipe: Array.isArray(saved.recipe) ? saved.recipe : (Array.isArray(form.recipe) ? form.recipe : null),
        addons: Array.isArray((saved as any).addons) ? (saved as any).addons : (Array.isArray((form as any).addons) ? (form as any).addons : null),
      });
      return;
    }

    onClose();
  };

  const handleDelete = async () => {
    if (!form.id) return;
    // Personal events / blocked time are just calendar holds with no
    // money attached — they delete cleanly. Real appointments get
    // cancelled (status flip) so the books keep a record, and any
    // Stripe deposit / balance gets refunded automatically.
    const isRealAppointment = form.kind !== "personal" && form.kind !== "blocked";

    if (!isRealAppointment) {
      const confirmCopy = form.kind === "personal"
        ? "Delete this personal event?"
        : "Remove this blocked time?";
      if (!window.confirm(confirmCopy)) return;
      await deleteAppointment(form.id);
      onClose();
      return;
    }

    // Real appointment — confirm with a refund warning if we know
    // there's a Stripe deposit or balance attached.
    const depositPaid = Number(form.depositPaid) || 0;
    const hasMoney = depositPaid > 0;
    const reason = window.prompt(
      hasMoney
        ? `Cancel this appointment and refund ${form.totalPrice ? "all collected payments" : "the deposit"}?\n\nOptional: reason for cancellation (visible only to you).`
        : "Cancel this appointment?\n\nOptional: reason for cancellation (visible only to you).",
      "",
    );
    if (reason === null) return; // user hit Cancel on the prompt

    // Ask whether to tell the client — so cancelling an accidental
    // booking doesn't email them. Honors the "Notify client" toggle:
    // when it's off we never ask and never notify.
    const clientReachable = (form.clientEmail || "").trim();
    const notifyOnCancel = notifyClient && !!clientReachable
      ? (await askNotify({ kind: "cancel", who: form.clientName || "the client", smsToo: false, contractNote: "", allowMessage: false })).notify
      : false;

    try {
      const supabase = getSupabase();
      const { data: sess } = await supabase.auth.getSession();
      const token = sess?.session?.access_token;
      if (!token) throw new Error("Sign in required.");
      const res = await fetch("/api/cancel-appointment", {
        method: "POST",
        headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
        body: JSON.stringify({ appointment_id: form.id, reason: reason || undefined, notify_client: notifyOnCancel }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body?.error || `cancel_${res.status}`);

      // CRITICAL: mirror the cancel into local React state. The
      // server already flipped status='cancelled' in the DB, but
      // `store.appointments` is the source of truth for every UI
      // view (Schedule, Dashboard, Money). Without this merge the
      // row keeps showing as active until the next full sync —
      // which was the production bug.
      const existing = store.appointments.find((a: any) => a?.id === form.id);
      if (existing) {
        await store.upsertAppointment({
          ...existing,
          status: "cancelled",
          cancelledAt: new Date().toISOString(),
          cancellationReason: reason || existing.cancellationReason || null,
        });
      }

      // Pull any still-pending automated reminders for this appointment
      // so they don't sit in the inbox (or fire at the client) for a
      // visit that's no longer happening. This cancel path writes the
      // status directly and doesn't run the reminder scheduler, so we
      // clear them explicitly.
      await store.cancelRemindersForAppt(form.id);

      if (body.refunded > 0) {
        alert(`Cancelled. Refunded $${Number(body.refunded).toFixed(2)} to the client via Stripe.`);
      } else if (body.failures?.length) {
        alert("Cancelled, but one or more refunds failed. Check Stripe and refund manually if needed.");
      } else {
        alert("Appointment cancelled.");
      }

      // A cancelled appointment shouldn't consume the client's account
      // credit — release anything that was applied back to their balance.
      try {
        if (form.clientId && form.id) {
          await applyCreditToAppointment(form.clientId, form.id, 0);
        }
      } catch { /* best-effort */ }

      // Offer to turn the cancellation into account credit for the client
      // — the "I'll credit you for the short notice" gesture. Applies to
      // their next appointment's balance and emails them automatically.
      try {
        if (store.userId && form.clientId) {
          const collected = depositPaid > 0 ? ` (you collected ${fmtMoney(depositPaid, business.currency)})` : "";
          const raw = window.prompt(
            `Give ${form.clientName || "this client"} account credit for the cancellation?${collected}\n\nEnter an amount to credit their account (or leave blank to skip). It applies to their next appointment's balance and they'll be emailed.`,
            "",
          );
          if (raw !== null) {
            const amt = Math.round((parseFloat(raw) || 0) * 100) / 100;
            if (amt > 0) {
              await grantCredit(
                store.userId,
                { id: form.clientId, name: form.clientName, email: form.clientEmail },
                amt,
                reason ? `Cancellation — ${reason}` : "Cancellation credit",
                { studioName: business?.name || business?.studioName || null },
              );
              alert(
                form.clientEmail
                  ? `Added ${fmtMoney(amt, business.currency)} credit to ${form.clientName || "the client"}'s account — they were emailed.`
                  : `Added ${fmtMoney(amt, business.currency)} credit to ${form.clientName || "the client"}'s account.`,
              );
            }
          }
        }
      } catch (e: any) {
        if (typeof console !== "undefined") console.warn("[appt] cancellation credit failed:", e?.message || e);
      }

      trackEvent("appointment_cancelled", { category: "feature", metadata: { refunded: body.refunded || 0 } });
    } catch (err: any) {
      console.error("[appt] cancel failed:", err);
      alert(`Couldn't cancel: ${err?.message || "Please try again."}`);
      return;
    }
    onClose();
  };

  // Hard-delete escape hatch for real appointments. "Cancel
  // appointment" keeps the row (status=cancelled) so the books
  // retain a record — cancelled rows are already excluded from
  // Reports by isBillable, so cancellation correctly updates the
  // numbers. But test/junk appointments leave clutter; this purges
  // them entirely so they're gone from history and reports for good.
  const handleHardDelete = async () => {
    if (!form.id) return;
    if (!window.confirm(
      "Permanently delete this appointment? This removes it from your schedule, history, and reports. This cannot be undone.",
    )) return;
    await store.cancelRemindersForAppt(form.id);
    // Retire the linked booking first so the cloud delete that follows
    // doesn't leave an orphaned, still-"approved" booking behind.
    await store.retireBookingForAppt(form.id);
    await deleteAppointment(form.id);
    onClose();
  };

  const handleDeleteSeries = async () => {
    if (!form.seriesId) return;
    if (!window.confirm("Cancel this entire recurring series? Past appointments stay; future ones are cancelled (and deposits refunded).")) return;
    const futures = appointments.filter(a => a.seriesId === form.seriesId && a.date >= todayISO());
    for (const f of futures) {
      // Reuse the cancel-and-refund route per future occurrence so
      // each Stripe charge gets refunded individually.
      try {
        const supabase = getSupabase();
        const { data: sess } = await supabase.auth.getSession();
        const token = sess?.session?.access_token;
        if (!token) continue;
        const res = await fetch("/api/cancel-appointment", {
          method: "POST",
          headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
          body: JSON.stringify({ appointment_id: f.id, reason: "recurring series cancelled" }),
        });
        if (res.ok) {
          // Mirror into local state for the same reason as above —
          // otherwise the series keeps showing as a wall of active
          // future appointments even after every cancel succeeded.
          await store.upsertAppointment({
            ...f,
            status: "cancelled",
            cancelledAt: new Date().toISOString(),
            cancellationReason: "recurring series cancelled",
          });
          await store.cancelRemindersForAppt(f.id);
        }
      } catch (e) {
        console.warn("[appt] series cancel failed for", f.id, e);
      }
    }
    await deleteSeries(form.seriesId);
    onClose();
  };

  // Phase 1 — operational speed:
  //   • Duplicate creates a new in-memory appointment record prefilled
  //     from the current one (id wiped so save creates a new row, date
  //     reset to today). Closes this sheet and reopens with the copy.
  //   • Quick reschedule opens a tiny date+time mini-sheet that writes
  //     ONLY those two fields, then closes — for the common case where
  //     a client moves their slot.
  const [showQuickReschedule, setShowQuickReschedule] = useState(false);
  const [rescheduleDate, setRescheduleDate] = useState<string>("");
  const [rescheduleTime, setRescheduleTime] = useState<string>("");
  const [rescheduleBusy, setRescheduleBusy] = useState(false);

  const handleDuplicate = () => {
    if (!form.id) return;
    const dup: any = {
      ...form,
      id: undefined,
      seriesId: undefined,
      date: todayISO(),
      status: "scheduled",
      depositPaid: 0,
      paymentStatus: "",
      paymentDate: "",
      paymentMethod: "",
      paymentNotes: "",
      // Drop the discount snapshot — duplicates start from the gross
      // price; the user re-applies a discount on the new appointment.
      discounts: [],
      discountId: null,
      discountName: null,
      discountAmount: 0,
    };
    onClose();
    // Defer so the parent can react to the close before we re-open.
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent("bbp:duplicate-appointment", { detail: dup }));
    }, 0);
  };

  // Rebook — one tap from the appointment to draft her NEXT install.
  // Reuses the duplicate pipeline (fresh status + cleared payment), but
  // pre-dates it to the service's typical rebook cadence so the stylist
  // lands on the right week instead of today.
  const handleRebook = () => {
    if (!form.id) return;
    const weeks = suggestRebookWeeks(form.style) || 6;
    const next: any = {
      ...form,
      id: undefined,
      seriesId: undefined,
      date: addDaysISO(todayISO(), weeks * 7),
      status: "scheduled",
      depositPaid: 0,
      paymentStatus: "",
      paymentDate: "",
      paymentMethod: "",
      paymentNotes: "",
      discounts: [],
      discountId: null,
      discountName: null,
      discountAmount: 0,
    };
    onClose();
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent("bbp:duplicate-appointment", { detail: next }));
    }, 0);
  };

  // Checkout — one tap to close out the appointment from the calendar:
  // collect the outstanding balance (net of any store credit already
  // applied), mark it paid + completed, persist, then drop straight
  // into the receipt. Consolidates the manual "mark paid → save →
  // generate receipt" steps into a single Vagaro-style action.
  const handleCheckout = async () => {
    if (!form.id) return;
    const netTotal = Math.max(0, parseMoney(form.totalPrice) - parseMoney(form.discountAmount));
    const creditApplied = Math.max(0, parseMoney(form.creditApplied));
    const collected = Math.max(0, netTotal - creditApplied);
    const canonical = Array.isArray(store?.appointments)
      ? store.appointments.find((x: any) => x?.id === form.id)
      : null;
    const original = (canonical && typeof canonical === "object") ? canonical
      : (appt && typeof appt === "object") ? appt : {};
    const checkedOut: any = {
      ...original,
      ...form,
      depositPaid: collected,
      creditApplied,
      paymentStatus: "paid",
      paymentDate: form.paymentDate || todayISO(),
      paymentMethod: form.paymentMethod || "cash",
      status: (!isCanceledAppointment(form) && form.status !== "no_show") ? "completed" : form.status,
    };
    const saved = await upsertAppointment(checkedOut);
    if (!saved) return; // Gated by upgrade sheet.
    if (openReceipt) {
      try {
        const clientName = clients.find((c: any) => c.id === form.clientId)?.name || form.clientName || "Client";
        const rcp = buildReceiptFromAppointment(saved, "receipt", receipts || [], `rcp_${uid()}`, clientName);
        const savedRcp = await upsertReceipt(rcp);
        onClose();
        openReceipt(savedRcp as ReceiptRecord);
        return;
      } catch {
        /* receipt is best-effort — the checkout itself already saved */
      }
    }
    onClose();
  };

  const openQuickReschedule = () => {
    setRescheduleDate(form.date || todayISO());
    setRescheduleTime(form.time || "10:00");
    setShowQuickReschedule(true);
  };

  const handleQuickReschedule = async () => {
    if (!form.id || rescheduleBusy) return;
    if (!rescheduleDate || !rescheduleTime) return;
    setRescheduleBusy(true);
    const next = { ...form, date: rescheduleDate, time: rescheduleTime };
    setForm(next);
    const saved = await upsertAppointment(next);
    setRescheduleBusy(false);
    if (saved) {
      setShowQuickReschedule(false);
      onClose();
    }
  };

  const handleStartTimer = () => {
    if (!form.id) return;
    openTimerForAppt(form);
    onClose();
  };

  // Sheet title + placeholder copy depend on the calendar item kind.
  const isAppointment = form.kind === "appointment" || !form.kind;
  const isPersonal = form.kind === "personal";
  const isBlocked = form.kind === "blocked";

  // ---- Editable add-ons -------------------------------------------
  // Resolve the service this appointment came from so we can offer its
  // defined optional extras as toggles. Manual / unlinked appointments
  // (no serviceId, or a service since deleted) simply get the custom
  // add-on entry below.
  const apptService = useMemo(() => {
    const list = (store.servicesApi?.services as Service[]) || [];
    return form.serviceId ? (list.find((s) => s.id === form.serviceId) || null) : null;
  }, [store.servicesApi?.services, form.serviceId]);
  const availableExtras = useMemo(
    () => ((apptService?.extras || []) as ServiceExtra[]).filter((e) => e?.active !== false),
    [apptService],
  );
  // Contract attached to this appointment's service — surfaced so the
  // stylist can see which agreement goes out with the booking (the app's
  // equivalent of Square's "Forms to send"). Contracts are assigned per
  // service in Settings → Services.
  const apptContracts = useContractTemplates(store.userId || null);
  const apptContractNames = useMemo(() => {
    const cid = (apptService as any)?.contract_template_id;
    const names: string[] = [];
    for (const t of apptContracts.contractTemplates || []) {
      if (!t.is_active) continue;
      if (t.attach_to_all_bookings || (cid && t.id === cid)) names.push(t.title);
    }
    return Array.from(new Set(names));
  }, [apptService, apptContracts.contractTemplates]);
  const currentAddons: any[] = Array.isArray(form.addons) ? form.addons : [];
  const isExtraSelected = (id: string) => currentAddons.some((a) => String(a?.id) === String(id));
  // Add-ons not backed by a current menu extra (custom one-offs, or
  // client-picked extras the service no longer lists). Rendered with a
  // remove control so they're still manageable.
  const orphanAddons = currentAddons.filter(
    (a) => !availableExtras.some((e) => String(e.id) === String(a?.id)),
  );
  // Round a duration to whole minutes to keep float noise out of the
  // hours field; "" when it lands at/under zero.
  const durationStr = (h: number) => {
    const r = Math.round(h * 60) / 60;
    return r > 0 ? String(r) : "";
  };
  // Add or remove a service extra, auto-adjusting total price and
  // duration by the extra's deltas. Manual edits to either field still
  // stick — we only move them on this explicit toggle.
  const toggleExtra = (extra: ServiceExtra) => {
    setForm((prev: any) => {
      const addons: any[] = Array.isArray(prev.addons) ? prev.addons : [];
      const exists = addons.some((a) => String(a?.id) === String(extra.id));
      const price = Number(extra.price) || 0;
      const durDelta = Number(extra.duration_hours_delta) || 0;
      const curTotal = parseMoney(prev.totalPrice);
      const curDur = Number(prev.durationHours) || 0;
      if (exists) {
        return {
          ...prev,
          addons: addons.filter((a) => String(a?.id) !== String(extra.id)),
          totalPrice: sanitizeMoneyInput(Math.max(0, roundCents(curTotal - price))),
          durationHours: durationStr(curDur - durDelta),
        };
      }
      return {
        ...prev,
        addons: [
          ...addons,
          {
            id: extra.id,
            name: extra.name,
            price,
            duration_hours_delta: durDelta,
            include_in_deposit: extra.include_in_deposit === true,
          },
        ],
        totalPrice: sanitizeMoneyInput(roundCents(curTotal + price)),
        durationHours: durationStr(curDur + durDelta),
      };
    });
  };
  const removeAddon = (id: string) => {
    setForm((prev: any) => {
      const addons: any[] = Array.isArray(prev.addons) ? prev.addons : [];
      const target = addons.find((a) => String(a?.id) === String(id));
      if (!target) return prev;
      const curTotal = parseMoney(prev.totalPrice);
      const curDur = Number(prev.durationHours) || 0;
      return {
        ...prev,
        addons: addons.filter((a) => String(a?.id) !== String(id)),
        totalPrice: sanitizeMoneyInput(Math.max(0, roundCents(curTotal - (Number(target.price) || 0)))),
        durationHours: durationStr(curDur - (Number(target.duration_hours_delta) || 0)),
      };
    });
  };
  const addCustomAddon = () => {
    const name = customAddonName.trim();
    const price = parseMoney(customAddonPrice);
    const durDelta = Number(customAddonHours) || 0;
    if (!name) return;
    setForm((prev: any) => {
      const addons: any[] = Array.isArray(prev.addons) ? prev.addons : [];
      const curTotal = parseMoney(prev.totalPrice);
      const curDur = Number(prev.durationHours) || 0;
      return {
        ...prev,
        addons: [
          ...addons,
          { id: `custom-${uid()}`, name, price, duration_hours_delta: durDelta, include_in_deposit: false, custom: true },
        ],
        totalPrice: sanitizeMoneyInput(roundCents(curTotal + price)),
        durationHours: durationStr(curDur + durDelta),
      };
    });
    setCustomAddonName("");
    setCustomAddonPrice("");
    setCustomAddonHours("");
  };

  // ---- Service options (variations) -------------------------------
  // The booking page's "Choose an option" picker maps to the service's
  // add_ons (variations) — each can carry its own price/duration/
  // deposit. Surface them here so a stylist can switch the option for a
  // client who booked the wrong one; switching re-prices the ticket.
  const serviceVariations = useMemo(
    () => (Array.isArray(apptService?.add_ons) ? (apptService!.add_ons as ServiceAddOn[]) : []),
    [apptService],
  );
  // Sum of the currently-picked extras (add-ons) — folded back on top
  // of the base/variation whenever the option changes so the total
  // stays "variation price + extras", matching the booking page.
  const extrasPriceTotal = currentAddons.reduce((s, a) => s + (Number(a?.price) || 0), 0);
  const extrasDurationTotal = currentAddons.reduce((s, a) => s + (Number(a?.duration_hours_delta) || 0), 0);
  // Switch the option. Passing null selects the base ("Standard").
  // Re-prices total + duration off the resolved variation (plus the
  // picked extras), updates the variation snapshot, and rewrites the
  // style/service label to the canonical "Service — Option" form so
  // the calendar + client emails read correctly. The already-collected
  // deposit is left untouched — the new balance reflects the change.
  const selectVariation = (variationId: string | null) => {
    if (!apptService) return;
    const resolved = resolveVariationPricing(apptService, variationId);
    const composedName = resolved.variationName
      ? `${apptService.name} — ${resolved.variationName}`
      : apptService.name;
    setForm((prev: any) => ({
      ...prev,
      variationId: resolved.variationId,
      variationName: resolved.variationName,
      style: composedName,
      totalPrice: sanitizeMoneyInput(roundCents(resolved.price + extrasPriceTotal)),
      durationHours: durationStr(resolved.durationHours + extrasDurationTotal),
    }));
  };

  // ---- Style customization (braiding-hair color / boho curl) -------
  // The booking page lets the client pick a braiding-hair color and,
  // for boho/curly options, a curl pattern (from the service's allowed
  // lists, or a custom value). Surface them here so a stylist can
  // correct a client's pick. Current values read the same precedence as
  // the read-only display did.
  const cust = (form.customization && typeof form.customization === "object") ? form.customization : {};
  const custSummary = (cust.summary && typeof cust.summary === "object") ? cust.summary : {};
  const hairColorValue = String(cust.hairColor ?? custSummary.custom_hair_color ?? "");
  const curlPatternValue = String(cust.curlPattern ?? custSummary.custom_curl_pattern ?? "");
  const styleNotesValue = String(cust.styleNotes ?? custSummary.notes ?? "");
  const allowedHairColors: string[] = Array.isArray((apptService as any)?.allowed_hair_colors)
    ? (apptService as any).allowed_hair_colors.filter(Boolean) : [];
  const allowedCurlPatterns: string[] = Array.isArray((apptService as any)?.allowed_curl_patterns)
    ? (apptService as any).allowed_curl_patterns.filter(Boolean) : [];
  // Show the hair-color editor when the service includes hair / offers
  // colors, or a value was already booked. Curl likewise. Keeps the
  // card off manual appointments that have no customization at all.
  const showHairColorEditor = !!(apptService as any)?.hair_included
    || allowedHairColors.length > 0 || !!hairColorValue;
  const showCurlEditor = !!(apptService as any)?.allow_client_curl_pattern_selection
    || allowedCurlPatterns.length > 0 || !!curlPatternValue;
  const setCustomizationField = (field: "hairColor" | "curlPattern" | "styleNotes", value: string) => {
    setForm((prev: any) => {
      const prevCust = (prev.customization && typeof prev.customization === "object") ? prev.customization : {};
      return { ...prev, customization: { ...prevCust, [field]: value } };
    });
  };

  const sheetTitle = (() => {
    if (form.id) {
      if (isPersonal) return "Edit personal event";
      if (isBlocked) return "Edit blocked time";
      return "Edit Appointment";
    }
    if (isPersonal) return "New personal event";
    if (isBlocked) return "Block off time";
    return "New Appointment";
  })();

  return (
    <Sheet open={open} onClose={onClose} title={sheetTitle}>
      <div className="space-y-4 pb-6">
        {!isAppointment && (
          <Field label="Title">
            <Input
              value={form.eventTitle || ""}
              onChange={e => setForm({ ...form, eventTitle: e.target.value })}
              placeholder={isPersonal ? "Lunch with Mom" : "Unavailable"}
            />
          </Field>
        )}

        {!isAppointment && (
          <Card className="p-3 space-y-3" style={{ background: C.cream }}>
            <div className="flex items-center justify-between gap-3">
              <div className="flex-1">
                <p className="text-[13px] font-semibold" style={{ color: C.espresso }}>All day</p>
                <p className="text-[11px]" style={{ color: C.muted }}>
                  {form.isAllDay
                    ? "This blocks your full booking day."
                    : "Toggle on to block the whole day from public booking."}
                </p>
              </div>
              <Toggle
                checked={!!form.isAllDay}
                onChange={(checked) => {
                  setForm({
                    ...form,
                    isAllDay: checked,
                    // Clear time + duration when switching to all-day so
                    // the row sorts to the top of the day cleanly and
                    // doesn't carry stale numbers if the user toggles back.
                    time: checked ? "" : form.time,
                    durationHours: checked ? "" : form.durationHours,
                    blocksAvailability: checked ? true : (form.blocksAvailability ?? true),
                  });
                }}
              />
            </div>
            <div className="flex items-center justify-between gap-3">
              <div className="flex-1">
                <p className="text-[13px] font-semibold" style={{ color: C.espresso }}>Block public availability</p>
                <p className="text-[11px]" style={{ color: C.muted }}>
                  When on, public clients can&apos;t book during this time.
                </p>
              </div>
              <Toggle
                checked={form.blocksAvailability !== false}
                onChange={(checked) => setForm({ ...form, blocksAvailability: checked })}
              />
            </div>
          </Card>
        )}

        {isAppointment && (
          <Field label="Client">
            {showNewClient ? (
              <div className="flex gap-2">
                <div className="flex-1"><Input value={newClientName} onChange={e => setNewClientName(e.target.value)} placeholder="Client name" /></div>
                <Button variant="outline" onClick={() => setShowNewClient(false)}>Cancel</Button>
              </div>
            ) : (
              <div className="flex gap-2">
                <div className="flex-1">
                  <Select value={form.clientId} onChange={e => setForm({ ...form, clientId: e.target.value, dependentId: null, dependentName: null })}
                    options={[{ value: "", label: "— Select client —" }, ...clients.map(c => ({ value: c.id, label: c.name }))]} />
                </div>
                <Button variant="outline" icon={<UserPlus size={16} />} onClick={() => setShowNewClient(true)}>New</Button>
              </div>
            )}
          </Field>
        )}

        {/* Booking for — record whether this appointment is for the
            client or one of their family members (kids/dependents). Shows
            whenever a saved client is selected; a family member can be
            added inline (e.g. "Carol — mom"), which also saves them to the
            client's profile. The client stays the contact + payer;
            dependentName just records who the style is for. */}
        {isAppointment && (() => {
          const selected = clients.find((c: any) => c.id === form.clientId);
          if (!selected) return null;
          const deps: any[] = Array.isArray(selected?.dependents) ? selected.dependents : [];
          return (
            <Field label="Booking for" hint="Who this appointment is for. Billing + reminders still go to the client.">
              <Select
                value={form.dependentId || ""}
                onChange={async (e: any) => {
                  const val = e.target.value;
                  if (val === "__add__") {
                    const name = (window.prompt("Family member's name (e.g. Carol — mom)") || "").trim();
                    if (name) {
                      const newDep = { id: `dep-${uid()}`, name, note: "" };
                      await upsertClient({ ...selected, dependents: [...deps, newDep] });
                      setForm({ ...form, dependentId: newDep.id, dependentName: newDep.name });
                    }
                    return;
                  }
                  const id = val || null;
                  const dep = deps.find((d) => String(d.id) === String(id));
                  setForm({ ...form, dependentId: id, dependentName: dep ? dep.name : null });
                }}
                options={[
                  { value: "", label: `${selected?.name || "Client"} (the client)` },
                  ...deps.map((d) => ({ value: d.id, label: d.name || "Family member" })),
                  { value: "__add__", label: "＋ Add family member…" },
                ]}
              />
            </Field>
          );
        })()}

        {isAppointment && (
          <div className="grid grid-cols-2 gap-3">
            <Field label="Phone" hint="for SMS"><Input type="tel" value={form.clientPhone} onChange={e => setForm({ ...form, clientPhone: e.target.value })} placeholder="555-0123" /></Field>
            <Field label="Email" hint="for email"><Input type="email" value={form.clientEmail} onChange={e => setForm({ ...form, clientEmail: e.target.value })} placeholder="name@email.com" /></Field>
          </div>
        )}

        {isAppointment && (
          <ServicePicker
            services={(store.servicesApi?.services as Service[]) || []}
            value={form.serviceId || null}
            onPick={(svc, mode) => applyServiceToForm(svc, mode)}
          />
        )}

        {isAppointment && (
          <Field label="Style / Service"><Input value={form.style} onChange={e => setForm({ ...form, style: e.target.value })} placeholder="e.g. Knotless mid-back" /></Field>
        )}

        {/* Service option (variation) picker. Mirrors the booking
            page's "Choose an option" — each option carries its own
            price/duration/deposit. Switching re-prices the ticket
            (Total price + Duration above) and rewrites the Style /
            Service label. Only shows when the linked service actually
            offers options. The already-collected deposit isn't touched
            — switching to a pricier option just raises the balance. */}
        {isAppointment && serviceVariations.length > 0 && (
          <Field label="Option" hint="Switching re-prices this appointment">
            <div className="space-y-1.5">
              {(() => {
                const base = resolveVariationPricing(apptService!, null);
                const rows = [
                  { id: null as string | null, resolved: base, description: null as string | null },
                  ...serviceVariations.map((v) => ({
                    id: v.id as string | null,
                    resolved: resolveVariationPricing(apptService!, v.id),
                    description: (v.variation_description || "").trim() || null,
                  })),
                ];
                const currentId = form.variationId || null;
                return rows.map((row) => {
                  const selected = String(row.id ?? "") === String(currentId ?? "");
                  const label = row.resolved.variationName || "Standard";
                  const meta: string[] = [];
                  if (row.resolved.durationHours > 0) meta.push(`${row.resolved.durationHours}h`);
                  if (row.resolved.depositRequired && row.resolved.depositAmount > 0) {
                    meta.push(`${fmtMoney(row.resolved.depositAmount, business?.currency)} deposit`);
                  }
                  return (
                    <button
                      key={row.id ?? "__base__"}
                      type="button"
                      onClick={() => selectVariation(row.id)}
                      aria-pressed={selected}
                      className="w-full flex items-start gap-2.5 text-left rounded-xl p-2.5"
                      style={{
                        background: selected ? C.ivory : "transparent",
                        border: `1px solid ${selected ? C.goldDeep : C.hairline}`,
                      }}
                    >
                      <span
                        aria-hidden
                        className="flex items-center justify-center rounded-full mt-0.5"
                        style={{
                          width: 18,
                          height: 18,
                          flex: "0 0 auto",
                          background: selected ? C.goldDeep : "transparent",
                          border: `1px solid ${selected ? C.goldDeep : C.hairline}`,
                        }}
                      >
                        {selected && <Check size={12} color={C.cream} />}
                      </span>
                      <span className="flex-1 min-w-0">
                        <span className="flex items-center justify-between gap-2">
                          <span className="text-[13px] font-semibold" style={{ color: C.espresso }}>{label}</span>
                          <span className="text-[13px] font-semibold" style={{ color: C.goldDeep, whiteSpace: "nowrap" }}>
                            {fmtMoney(row.resolved.price, business?.currency)}
                          </span>
                        </span>
                        {meta.length > 0 && (
                          <span className="block text-[11px] mt-0.5" style={{ color: C.muted }}>{meta.join(" · ")}</span>
                        )}
                        {row.description && (
                          <span className="block text-[11px] mt-0.5" style={{ color: C.coffee, lineHeight: 1.4 }}>{row.description}</span>
                        )}
                      </span>
                    </button>
                  );
                });
              })()}
            </div>
          </Field>
        )}

        <div className="grid grid-cols-2 gap-3">
          <Field label="Date"><Input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></Field>
          {!form.isAllDay && (
            <Field label="Time"><Input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} /></Field>
          )}
          {!form.isAllDay && (
            <Field label="Duration"><MoneyInput prefix="" suffix="hrs" placeholder="6.5" value={form.durationHours} onChange={(v) => setForm({ ...form, durationHours: v })} /></Field>
          )}
          {isAppointment && (
            <Field label="Status">
              <Select value={form.status} onChange={e => setForm({ ...form, status: e.target.value })}
                options={[
                  { value: "scheduled", label: "Scheduled" },
                  { value: "confirmed", label: "Confirmed" },
                  { value: "completed", label: "Completed" },
                  { value: "cancelled", label: "Cancelled" },
                  { value: "no_show", label: "No-show" },
                ]} />
            </Field>
          )}
          {isAppointment && form.status === "no_show" && form.id && (
            <NoShowProtectionCard
              store={store}
              appointmentId={String(form.id)}
              servicePrice={parseMoney(form.totalPrice)}
            />
          )}
          {isAppointment && (form.status === "cancelled" || form.status === "canceled") && (
            <CancelledWaitlistNotify
              store={store}
              date={form.date}
              time={form.time}
              style={form.style}
            />
          )}
          {isAppointment && <Field label="Total price"><MoneyInput value={form.totalPrice} onChange={(v) => setForm({ ...form, totalPrice: v })} /></Field>}
          {isAppointment && (() => {
            // The stored amount doubles as "total collected" once the
            // balance is paid (existing behavior, intentionally left in
            // place). Relabel so a paid-in-full appointment doesn't
            // confusingly read as a giant "deposit".
            const tp = parseMoney(form.totalPrice);
            const dp = parseMoney(form.depositPaid);
            const paidInFull = form.paymentStatus === "paid" || (tp > 0 && dp >= tp);
            return (
              <Field label={paidInFull ? "Total paid" : "Deposit paid"}>
                <MoneyInput value={form.depositPaid} onChange={(v) => setForm({ ...form, depositPaid: v })} />
              </Field>
            );
          })()}
        </div>

        {isAppointment && (
          <Card className="p-3.5">
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold" style={{ color: C.espresso }}>Request a deposit</p>
                <p className="text-[11px]" style={{ color: C.muted }}>
                  Off by default for appointments you create here. Turn on to mark a deposit as expected — it'll show on the dashboard's Deposits due list until paid.
                </p>
              </div>
              <Toggle
                checked={!!form.depositRequired}
                onChange={(v: boolean) => setForm({ ...form, depositRequired: v })}
              />
            </div>
            {form.source && (
              <p className="mt-2 text-[10px]" style={{ color: C.muted }}>
                Source: {form.source === "public_booking" ? "Booking link" : form.source === "manual" ? "Manual" : form.source}
              </p>
            )}
          </Card>
        )}

        {/* Add-ons — editable. Lets the stylist add or remove the
            service's optional extras (or a one-off custom add-on)
            after booking — e.g. a client who forgot to pick the "hair
            included" option. Toggling an extra auto-adjusts Total
            price + Duration above; both stay editable by hand. Always
            available on real appointments so a manual booking can get
            a custom add-on even with no service menu behind it. */}
        {isAppointment && (
          <Card className="p-3.5">
            <p className="text-sm font-semibold mb-1" style={{ color: C.espresso }}>Add-ons</p>
            <p className="text-[11px]" style={{ color: C.muted, lineHeight: 1.4 }}>
              Optional extras for this appointment. Adding or removing one updates the total price and duration above — you can still edit those by hand.
            </p>

            {/* Service menu extras as toggles. Checked = on this
                appointment (covers both client-picked and ones you
                add here). */}
            {availableExtras.length > 0 && (
              <ul className="mt-3 space-y-1.5" style={{ listStyle: "none", padding: 0, margin: 0 }}>
                {availableExtras.map((e) => {
                  const selected = isExtraSelected(e.id);
                  const durDelta = Number(e.duration_hours_delta) || 0;
                  return (
                    <li key={e.id}>
                      <button
                        type="button"
                        onClick={() => toggleExtra(e)}
                        aria-pressed={selected}
                        className="w-full flex items-center gap-2.5 text-left rounded-xl p-2.5"
                        style={{
                          background: selected ? C.ivory : "transparent",
                          border: `1px solid ${selected ? C.goldDeep : C.hairline}`,
                        }}
                      >
                        <span
                          aria-hidden
                          className="flex items-center justify-center rounded-md"
                          style={{
                            width: 20,
                            height: 20,
                            flex: "0 0 auto",
                            background: selected ? C.goldDeep : "transparent",
                            border: `1px solid ${selected ? C.goldDeep : C.hairline}`,
                          }}
                        >
                          {selected && <Check size={14} color={C.cream} />}
                        </span>
                        <span className="flex-1 min-w-0 text-[12px]" style={{ lineHeight: 1.4 }}>
                          <span style={{ color: C.espresso, fontWeight: 600 }}>{e.name || "Add-on"}</span>
                          <span style={{ color: C.muted }}>
                            {" "}{(Number(e.price) || 0) > 0 ? `+${fmtMoney(Number(e.price) || 0, business?.currency)}` : "Free"}
                            {durDelta > 0 ? ` · +${durDelta}h` : ""}
                            {e.include_in_deposit ? " · in deposit" : ""}
                          </span>
                        </span>
                      </button>
                    </li>
                  );
                })}
              </ul>
            )}

            {/* Add-ons on the appointment that aren't in the current
                service menu — custom ones you added, or client-picked
                extras the service no longer lists. Editable via remove
                so they're never stranded. */}
            {orphanAddons.length > 0 && (
              <ul className="mt-2 space-y-1.5" style={{ listStyle: "none", padding: 0, margin: 0 }}>
                {orphanAddons.map((a: any, i: number) => (
                  <li
                    key={a?.id || i}
                    className="flex items-center justify-between gap-2 rounded-xl p-2.5"
                    style={{ background: C.ivory, border: `1px solid ${C.hairline}` }}
                  >
                    <span className="flex-1 min-w-0 text-[12px]" style={{ color: C.coffee, lineHeight: 1.4 }}>
                      <span style={{ color: C.espresso, fontWeight: 600 }}>{a?.name || "Add-on"}</span>
                      <span style={{ color: C.muted }}>
                        {" "}+{fmtMoney(Number(a?.price) || 0, business?.currency)}
                        {Number(a?.duration_hours_delta) > 0 ? ` · +${Number(a.duration_hours_delta)}h` : ""}
                        {a?.include_in_deposit ? " · in deposit" : ""}
                      </span>
                    </span>
                    <button
                      type="button"
                      onClick={() => removeAddon(a?.id)}
                      className="p-1.5 rounded-lg"
                      style={{ color: C.danger, flex: "0 0 auto" }}
                      aria-label={`Remove ${a?.name || "add-on"}`}
                    >
                      <Trash2 size={16} />
                    </button>
                  </li>
                ))}
              </ul>
            )}

            {/* One-off custom add-on. Commits on the Add button so the
                total/duration only move on an explicit action. */}
            <div className="mt-3 rounded-xl p-3" style={{ background: C.ivory, border: `1px solid ${C.hairline}` }}>
              <p className="text-[12px] font-semibold mb-2" style={{ color: C.espresso }}>Add a custom add-on</p>
              <Input
                value={customAddonName}
                onChange={(ev: any) => setCustomAddonName(ev.target.value)}
                placeholder="Name (e.g. Hair included)"
              />
              <div className="grid grid-cols-2 gap-2 mt-2">
                <Field label="Price">
                  <MoneyInput value={customAddonPrice} onChange={(v: any) => setCustomAddonPrice(v)} />
                </Field>
                <Field label="Extra time (hrs)" hint="Optional">
                  <Input
                    type="number"
                    inputMode="decimal"
                    step="0.25"
                    min={0}
                    value={customAddonHours}
                    onChange={(ev: any) => setCustomAddonHours(ev.target.value)}
                    placeholder="0"
                  />
                </Field>
              </div>
              <div className="mt-2">
                <Button
                  variant="outline"
                  icon={<Plus size={14} />}
                  onClick={addCustomAddon}
                  disabled={!customAddonName.trim()}
                >
                  Add add-on
                </Button>
              </div>
            </div>
          </Card>
        )}

        {/* Style customization — editable. The braiding-hair color and
            boho/curl pattern the client picked at booking can be
            corrected here; quick-pick chips come from the service's
            allowed lists, with a free-text override. Any other
            customization fields (e.g. "Hair included") stay read-only
            below. Edits sync to the booking_request so the client
            portal + emails reflect them. */}
        {isAppointment && (() => {
          const otherEntries = customizationEntries(form.customization).filter(
            (e) => e.label !== "Hair color" && e.label !== "Curl pattern" && e.label !== "Style notes",
          );
          if (!showHairColorEditor && !showCurlEditor && otherEntries.length === 0 && !styleNotesValue) {
            return null;
          }
          const chipRow = (options: string[], value: string, field: "hairColor" | "curlPattern") =>
            options.length > 0 ? (
              <div className="flex flex-wrap gap-1.5 mb-2">
                {options.map((opt) => {
                  const active = value.trim().toLowerCase() === opt.trim().toLowerCase();
                  return (
                    <button
                      key={opt}
                      type="button"
                      onClick={() => setCustomizationField(field, opt)}
                      className="text-[12px] px-2.5 py-1 rounded-full"
                      style={{
                        background: active ? C.goldDeep : C.ivory,
                        color: active ? C.cream : C.espresso,
                        border: `1px solid ${active ? C.goldDeep : C.hairline}`,
                      }}
                    >
                      {opt}
                    </button>
                  );
                })}
              </div>
            ) : null;
          return (
            <Card className="p-3.5">
              <p className="text-sm font-semibold mb-1" style={{ color: C.espresso }}>Style customization</p>
              <p className="text-[11px]" style={{ color: C.muted, lineHeight: 1.4 }}>
                Picked by the client at booking. Edit to correct it — changes sync to their appointment details.
              </p>
              <div className="mt-3 space-y-3">
                {showHairColorEditor && (
                  <Field label="Braiding hair color">
                    {chipRow(allowedHairColors, hairColorValue, "hairColor")}
                    <Input
                      value={hairColorValue}
                      onChange={(e: any) => setCustomizationField("hairColor", e.target.value)}
                      placeholder="e.g. 1B"
                    />
                  </Field>
                )}
                {showCurlEditor && (
                  <Field label="Curl pattern (boho hair)">
                    {chipRow(allowedCurlPatterns, curlPatternValue, "curlPattern")}
                    <Input
                      value={curlPatternValue}
                      onChange={(e: any) => setCustomizationField("curlPattern", e.target.value)}
                      placeholder="e.g. 4C, Spanish wave"
                    />
                  </Field>
                )}
                <Field label="Style notes" hint="Optional">
                  <Textarea
                    value={styleNotesValue}
                    onChange={(e: any) => setCustomizationField("styleNotes", e.target.value)}
                    rows={2}
                    placeholder="Anything the client noted about the look"
                  />
                </Field>
                {otherEntries.length > 0 && (
                  <ul className="space-y-1.5 pt-1" style={{ listStyle: "none", padding: 0, margin: 0 }}>
                    {otherEntries.map((e, i) => (
                      <li
                        key={i}
                        className="text-[12px] flex items-start justify-between gap-3"
                        style={{ color: C.coffee, lineHeight: 1.4 }}
                      >
                        <span style={{ color: C.muted, whiteSpace: "nowrap" }}>{e.label}</span>
                        <span style={{ color: C.espresso, fontWeight: 600, textAlign: "right" }}>{e.value}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </Card>
          );
        })()}

        {isAppointment && (() => {
          const intake = intakeAnswerEntries(appt as any);
          if (intake.length === 0) return null;
          return (
            <Card className="p-3.5">
              <p className="text-sm font-semibold mb-1" style={{ color: C.espresso }}>Consultation</p>
              <p className="text-[11px]" style={{ color: C.muted, lineHeight: 1.4 }}>
                Answered by the client at booking.
              </p>
              <ul className="mt-2 space-y-2" style={{ listStyle: "none", padding: 0, margin: 0 }}>
                {intake.map((e, i) => (
                  <li key={i} className="text-[12px]" style={{ lineHeight: 1.45 }}>
                    <span style={{ color: C.muted, display: "block" }}>{e.q}</span>
                    <span style={{ color: C.espresso, fontWeight: 600 }}>{e.a}</span>
                  </li>
                ))}
              </ul>
            </Card>
          );
        })()}

        {isAppointment && (
        <Field
          label="Discounts"
          hint={availableDiscounts.length === 0 && appliedDiscounts.length === 0
            ? "Create a Studio Offer in Settings → Discounts."
            : "Optional. Stack as many as you like — each subtracts from the total."}
        >
          {/* Applied discounts — each can be removed individually. */}
          {appliedDiscounts.length > 0 && (
            <ul className="space-y-2 mb-2" style={{ listStyle: "none", padding: 0, margin: "0 0 8px" }}>
              {appliedDiscounts.map(d => {
                const def = allDiscounts.find(x => x.id === d.id);
                const isLive = availableDiscounts.some(x => x.id === d.id);
                return (
                  <li key={d.id}
                    className="flex items-center justify-between gap-2 p-2.5 rounded-xl"
                    style={{ background: C.paper, border: `1px solid ${C.hairline}` }}>
                    <div className="min-w-0">
                      <p className="text-[13px] font-semibold truncate" style={{ color: C.espresso }}>
                        {d.name || "Discount"}
                        {def && !isLive ? " (paused)" : ""}
                      </p>
                      <p className="text-[11px]" style={{ color: C.goldDeep }}>
                        {def ? `${formatDiscountValue(def)} · ` : ""}− {fmtMoney(d.amount, business.currency)}
                      </p>
                    </div>
                    <button type="button" onClick={() => removeDiscount(d.id)}
                      aria-label={`Remove ${d.name || "discount"}`}
                      className="p-1.5 rounded-full active:scale-95 transition shrink-0"
                      style={{ color: C.muted }}>
                      <X size={16} />
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
          {/* Add another discount. Resets to the placeholder after each pick. */}
          {addableDiscounts.length > 0 && (
            <Select
              value=""
              onChange={e => addDiscount(e.target.value)}
              options={[
                { value: "", label: appliedDiscounts.length > 0 ? "Add another discount…" : "Add a discount…" },
                ...addableDiscounts.map(d => ({
                  value: d.id,
                  label: `${d.name} — ${formatDiscountValue(d)}`,
                })),
              ]}
            />
          )}
        </Field>
        )}
        {isAppointment && discountAmt > 0 && (
          <Card className="p-3" style={{ background: C.paper, border: `1px solid ${C.hairline}` }}>
            <div className="flex items-center justify-between text-[13px]" style={{ color: C.coffee }}>
              <span>Subtotal</span>
              <span style={{ fontFamily: "ui-monospace, SFMono-Regular, monospace" }}>
                {fmtMoney(grossTotal, business.currency)}
              </span>
            </div>
            {/* One line per applied discount so the math reads honestly. */}
            {appliedDiscounts.filter(d => d.amount > 0).map(d => (
              <div key={d.id} className="flex items-center justify-between text-[13px] mt-1" style={{ color: C.goldDeep }}>
                <span className="truncate pr-2">Discount{d.name ? ` — ${d.name}` : ""}</span>
                <span style={{ fontFamily: "ui-monospace, SFMono-Regular, monospace" }}>
                  − {fmtMoney(d.amount, business.currency)}
                </span>
              </div>
            ))}
            <div className="flex items-center justify-between text-[14px] font-semibold mt-2 pt-2"
              style={{ color: C.espresso, borderTop: `1px solid ${C.hairline}` }}>
              <span>Net total</span>
              <span style={{ fontFamily: "ui-monospace, SFMono-Regular, monospace" }}>
                {fmtMoney(netTotal, business.currency)}
              </span>
            </div>
          </Card>
        )}

        {/* Account credit — applied to the balance (not the deposit).
            Auto-suggests the available credit; the stylist can toggle it
            off. The ledger is reconciled on save. */}
        {isAppointment && creditPool > 0 && (
        <Card className="p-3.5" style={{ background: C.paper, border: `1px solid ${C.hairline}` }}>
          <div className="flex items-center justify-between gap-3">
            <div className="min-w-0">
              <p className="text-sm font-semibold" style={{ color: C.espresso }}>Account credit</p>
              <p className="text-[11px]" style={{ color: C.muted }}>
                {fmtMoney(creditPool, business.currency)} available · applied to the balance
              </p>
            </div>
            <Toggle
              checked={creditApplied > 0}
              onChange={(v: boolean) =>
                setForm((prev: any) => ({
                  ...prev,
                  creditApplied: v ? roundCents(maxCreditApplicable) : 0,
                }))
              }
            />
          </div>
          {creditApplied > 0 && (
            <div className="flex items-center justify-between text-[13px] mt-2 pt-2"
              style={{ color: C.goldDeep, borderTop: `1px solid ${C.hairline}` }}>
              <span>Credit applied</span>
              <span style={{ fontFamily: "ui-monospace, SFMono-Regular, monospace" }}>
                − {fmtMoney(creditApplied, business.currency)}
              </span>
            </div>
          )}
        </Card>
        )}

        {isAppointment && (
        <Card className="p-3.5 flex justify-between items-center" style={{ background: C.ivory }}>
          <span className="text-sm font-semibold" style={{ color: C.coffee }}>Balance due</span>
          <span style={{ fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 600, color: balanceDue > 0 ? C.warning : C.success }}>
            {fmtMoney(balanceDue, business.currency)}
          </span>
        </Card>
        )}

        {/* PAYMENT */}
        {isAppointment && (
        <Card className="p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <DollarSign size={16} style={{ color: C.gold }} />
              <span className="font-semibold text-sm" style={{ color: C.espresso }}>Payment</span>
            </div>
            <Pill tone={PAYMENT_STATUS_TONE[paymentStatusOf(form, todayISO())]}>
              {PAYMENT_STATUS_LABEL[paymentStatusOf(form, todayISO())]}
            </Pill>
          </div>
          {balanceDue > 0 ? (
            <>
              {/* Stripe balance payment link — copy the public /pay
                  page URL so the stylist can text it / DM it to the
                  client. The actual checkout session is created
                  server-side when the client taps Pay on that page. */}
              {/* Always available once a balance is owed on a saved
                  appointment. The opaque balance_access_token is a
                  DB-only column (set by trigger, backfilled for all
                  rows) — never gate the button on the local copy,
                  which can be stale right after an edit. Resolve it
                  lazily: in-memory → fresh DB read → safe owner
                  backfill RPC. */}
              {appt?.id && (
                <Button
                  variant="outline"
                  icon={<Copy size={16} />}
                  fullWidth
                  onClick={async () => {
                    let token: string | null =
                      appt?.balanceAccessToken || form?.balanceAccessToken || null;
                    if (!token) {
                      try {
                        const supabase = getSupabase();
                        const { data } = await supabase
                          .from("appointments")
                          .select("balance_access_token")
                          .eq("id", appt.id)
                          .maybeSingle();
                        token = (data as any)?.balance_access_token || null;
                        if (!token) {
                          const { data: gen } = await supabase
                            .rpc("ensure_appointment_balance_token", { appt_id_in: appt.id });
                          token = (typeof gen === "string" && gen) ? gen : null;
                        }
                      } catch { /* fall through to the guard below */ }
                    }
                    if (!token) {
                      alert("Couldn't generate the payment link just now. Please try again in a moment.");
                      return;
                    }
                    const url = `${typeof window !== "undefined" ? window.location.origin : ""}/pay/balance/${token}`;
                    try {
                      if (typeof navigator !== "undefined" && navigator.clipboard) {
                        await navigator.clipboard.writeText(url);
                        alert("Balance payment link copied.\n\nText or email it to your client — they'll pay through Stripe.");
                      } else {
                        // Older Safari — surface the URL so the
                        // stylist can long-press / copy manually.
                        window.prompt("Copy this link to share with your client:", url);
                      }
                      trackEvent("balance_link_copied", { category: "feature", metadata: { appt: String(appt.id).slice(0, 8) } });
                    } catch {
                      window.prompt("Copy this link to share with your client:", url);
                    }
                  }}
                >
                  Copy balance payment link
                </Button>
              )}
              <Button variant="primary" icon={<Check size={16} />} fullWidth
                onClick={() => {
                  const apptDate = form.date || todayISO();
                  const isPastOrToday = apptDate <= todayISO();
                  const netTotal = Math.max(0, parseMoney(form.totalPrice) - parseMoney(form.discountAmount));
                  // Record CASH collected — net of any store credit already
                  // applied — so collected revenue doesn't double-count the
                  // credit. normalizeAppointment recomputes balanceDue to 0.
                  const creditApplied = Math.max(0, parseMoney(form.creditApplied));
                  setForm({
                    ...form,
                    depositPaid: Math.max(0, netTotal - creditApplied),
                    paymentStatus: "paid",
                    paymentDate: form.paymentDate || todayISO(),
                    status: isPastOrToday && !isCanceledAppointment(form) && form.status !== "no_show"
                      ? "completed"
                      : form.status,
                  });
                }}>
                Mark balance paid (manual)
              </Button>
              {form.status === "completed" && (
                <Button variant="outline" icon={<RefreshCw size={14} />} fullWidth className="mt-2"
                  onClick={async () => {
                    // Stuck state: completed but with a balance due (e.g. a
                    // checkout reset under the old code that left status
                    // "completed"). Fully un-complete it so it leaves
                    // earnings, and drop any receipt.
                    const net = Math.max(0, (Number(form.totalPrice) || 0) - (Number(form.discountAmount) || 0));
                    setForm({
                      ...form,
                      depositPaid: 0,
                      balanceDue: net,
                      paymentStatus: "pending",
                      paymentDate: "",
                      paymentMethod: "",
                      paymentNotes: "",
                      status: "confirmed",
                    });
                    if (form.id && deleteReceipt) {
                      for (const r of (receipts || []).filter((x: any) => x.appointmentId === form.id)) {
                        try { await deleteReceipt(r.id); } catch { /* best-effort */ }
                      }
                    }
                  }}>
                  Reset checkout (un-complete)
                </Button>
              )}
            </>
          ) : (
            <Button variant="outline" icon={<RefreshCw size={14} />} fullWidth
              onClick={async () => {
                const net = Math.max(0, (Number(form.totalPrice) || 0) - (Number(form.discountAmount) || 0));
                setForm({
                  ...form,
                  depositPaid: 0,
                  balanceDue: net,
                  paymentStatus: "pending",
                  paymentDate: "",
                  paymentMethod: "",
                  paymentNotes: "",
                  // Reverse the checkout's completion too, so the
                  // appointment drops out of earnings (Total earned / yearly)
                  // and Money income — those count status==="completed" OR
                  // paymentStatus==="paid". "confirmed" (not "scheduled")
                  // avoids a spurious "Late" badge on a past date.
                  status: form.status === "completed" ? "confirmed" : form.status,
                });
                // Remove any receipt generated for this appointment so it
                // leaves the Money page's Receipts & Invoices list.
                if (form.id && deleteReceipt) {
                  for (const r of (receipts || []).filter((x: any) => x.appointmentId === form.id)) {
                    try { await deleteReceipt(r.id); } catch { /* best-effort */ }
                  }
                }
              }}>
              Reset payment
            </Button>
          )}
          <div className="grid grid-cols-2 gap-3 mt-3">
            <Field label="Payment date" hint="optional">
              <Input type="date" value={form.paymentDate || ""} onChange={e => setForm({ ...form, paymentDate: e.target.value })} />
            </Field>
            <Field label="Method" hint="optional">
              <Select value={form.paymentMethod || ""} onChange={e => setForm({ ...form, paymentMethod: e.target.value })} options={PAYMENT_METHODS} />
            </Field>
          </div>
          <div className="mt-3">
            <Field label="Payment notes" hint="optional">
              <Textarea value={form.paymentNotes || ""} onChange={e => setForm({ ...form, paymentNotes: e.target.value })} placeholder="Receipt #, tip amount, anything to remember…" rows={2} />
            </Field>
          </div>
          {form.id && openReceipt && (() => {
            const showReceipt = parseMoney(form.depositPaid) > 0 || form.paymentStatus === "paid" || form.paymentStatus === "partial" || form.status === "completed";
            const showInvoice = parseMoney(form.balanceDue) > 0 && form.paymentStatus !== "paid";
            if (!showReceipt && !showInvoice) return null;
            const handleGenerate = async (type: "receipt" | "invoice") => {
              const clientName = clients.find((c: any) => c.id === form.clientId)?.name || form.clientName || "Client";
              const newId = `rcp_${uid()}`;
              const rcp = buildReceiptFromAppointment(form, type, receipts || [], newId, clientName);
              const saved = await upsertReceipt(rcp);
              openReceipt(saved as ReceiptRecord);
            };
            return (
              <div className="grid grid-cols-2 gap-2 mt-3">
                {showReceipt && (
                  <Button variant="outline" icon={<Receipt size={14} />} onClick={() => handleGenerate("receipt")}>Generate receipt</Button>
                )}
                {showInvoice && (
                  <Button variant="outline" icon={<FileText size={14} />} onClick={() => handleGenerate("invoice")}>Generate invoice</Button>
                )}
              </div>
            );
          })()}
        </Card>
        )}

        {/* IN-PERSON PAYMENT — how to collect at the chair today, plus a
            forward-looking note. The seam (paymentMethod "tap_to_pay")
            is already in place, so the in-app Tap to Pay flow drops in
            here later without a data change. Shown only while a balance
            is actually owed. */}
        {isAppointment && form.id && balanceDue > 0 && form.paymentStatus !== "paid" && (
          <Card className="p-4" style={{ background: C.paper, border: `1px solid ${C.hairline}` }}>
            <div className="flex items-center gap-2 mb-2">
              <DollarSign size={16} style={{ color: C.gold }} />
              <span className="font-semibold text-sm" style={{ color: C.espresso }}>In-person payment</span>
              <Pill tone="gold">{isNative && ttpSupported && business?.tapToPayEnabled ? "Tap to Pay" : "Tap to Pay soon"}</Pill>
            </div>
            {isNative && ttpSupported && business?.tapToPayEnabled ? (
              // Live Tap to Pay on iPhone. Charges the balance on the
              // stylist's connected account via the native Stripe Terminal
              // reader, then mirrors the manual "Mark balance paid" state
              // (method = tap_to_pay, PI id in notes) so the save persists
              // it the same way. Nothing is written until they tap Save.
              <>
                <p className="text-[12px]" style={{ color: C.coffee, lineHeight: 1.5 }}>
                  Accept the card right on your iPhone — hold the client&apos;s card or phone near the top of yours. No reader needed.
                </p>
                <Button
                  variant="primary"
                  fullWidth
                  className="mt-3"
                  disabled={ttpBusy}
                  icon={<DollarSign size={16} />}
                  onClick={async () => {
                    if (ttpBusy) return;
                    setTtpMsg(null);
                    setTtpPaid(false);
                    setTtpStatus(null);
                    setTtpBusy(true);
                    try {
                      const res = await collectTapToPay({
                        amountCents: Math.round(balanceDue * 100),
                        appointmentId: form.id,
                        clientName: form.clientName || undefined,
                        currency: (business?.currency || "USD").toLowerCase(),
                        description: `${form.style || "Appointment"}${form.clientName ? ` — ${form.clientName}` : ""}`,
                        onStatus: (s) => setTtpStatus(s),
                      });
                      if (res.ok) {
                        const netTotal = Math.max(0, parseMoney(form.totalPrice) - parseMoney(form.discountAmount));
                        const creditUsed = Math.max(0, parseMoney(form.creditApplied));
                        const apptDate = form.date || todayISO();
                        const isPastOrToday = apptDate <= todayISO();
                        setForm({
                          ...form,
                          depositPaid: Math.max(0, netTotal - creditUsed),
                          paymentStatus: "paid",
                          paymentMethod: "tap_to_pay",
                          paymentDate: form.paymentDate || todayISO(),
                          paymentNotes: [form.paymentNotes, `Tap to Pay · ${res.paymentIntentId}`].filter(Boolean).join(" · "),
                          status: isPastOrToday && !isCanceledAppointment(form) && form.status !== "no_show" ? "completed" : form.status,
                        });
                        setTtpMsg({ kind: "ok", text: `Charged ${fmtMoney(balanceDue, business.currency)}. Tap Save to keep it.` });
                        setTtpPaid(true);
                      } else if (!res.canceled) {
                        setTtpMsg({ kind: "error", text: res.error });
                      }
                    } catch {
                      setTtpMsg({ kind: "error", text: "Tap to Pay didn't go through. Try again." });
                    } finally {
                      setTtpBusy(false);
                      setTtpStatus(null);
                    }
                  }}
                >
                  {ttpBusy ? "Starting Tap to Pay…" : `Tap to Pay ${fmtMoney(balanceDue, business.currency)}`}
                </Button>

                {/* Configuration / charge progress — App Review requires a
                    clear status indicator while the reader is prepared. */}
                {ttpBusy && ttpStatus && (
                  <div className="mt-2" aria-live="polite">
                    <div className="flex items-center gap-2">
                      <RefreshCw size={13} className="animate-spin" style={{ color: C.gold }} />
                      <span className="text-[12px]" style={{ color: C.coffee }}>
                        {TAP_TO_PAY_STAGE_LABEL[ttpStatus.stage]}
                      </span>
                    </div>
                    {ttpStatus.stage === "updating" && typeof ttpStatus.progress === "number" && (
                      <div className="mt-1.5 h-1.5 w-full rounded-full overflow-hidden" style={{ background: C.hairline }}>
                        <div className="h-full rounded-full" style={{ width: `${Math.round((ttpStatus.progress || 0) * 100)}%`, background: C.gold, transition: "width 200ms ease" }} />
                      </div>
                    )}
                  </div>
                )}

                {ttpMsg && (
                  <p className="text-[12px] mt-2" style={{ color: ttpMsg.kind === "ok" ? C.success : C.danger, lineHeight: 1.4 }}>
                    {ttpMsg.text}
                  </p>
                )}

                {/* Post-payment: offer the client a digital receipt. Reuses
                    the receipt builder + ReceiptSheet (share / text / email
                    / PDF), so the customer can always get a receipt. */}
                {ttpPaid && openReceipt && (
                  <div className="mt-3 rounded-xl p-3" style={{ background: C.ivory, border: `1px solid ${C.hairline}` }}>
                    <p className="text-[12px] font-semibold" style={{ color: C.espresso }}>Give your client a receipt?</p>
                    <div className="grid grid-cols-2 gap-2 mt-2">
                      <Button
                        variant="outline"
                        icon={<Receipt size={14} />}
                        onClick={async () => {
                          const clientName = clients.find((c: any) => c.id === form.clientId)?.name || form.clientName || "Client";
                          const rcp = buildReceiptFromAppointment({ ...form, paymentMethod: "tap_to_pay", paymentStatus: "paid" }, "receipt", receipts || [], `rcp_${uid()}`, clientName);
                          const saved = await upsertReceipt(rcp);
                          setTtpPaid(false);
                          openReceipt(saved as ReceiptRecord);
                        }}
                      >
                        Send receipt
                      </Button>
                      <Button variant="ghost" onClick={() => setTtpPaid(false)}>No receipt</Button>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <>
                <p className="text-[12px]" style={{ color: C.coffee, lineHeight: 1.5 }}>
                  {isNative && ttpSupported && !business?.tapToPayEnabled
                    ? "Tap to Pay on iPhone is available on this device — turn it on in Settings → Payments → Tap to Pay to charge cards right here. Until then, collect in person two ways:"
                    : isNative
                    ? "Tap to Pay on iPhone is coming to this app — accept cards on your phone, no reader needed. Until then, collect in person two ways:"
                    : "Tap to Pay on iPhone is coming to the Braid Boss Pro app — accept cards on your phone, no reader needed. Until then, collect in person two ways:"}
                </p>
                <ul className="mt-2 space-y-2" style={{ listStyle: "none", padding: 0, margin: 0 }}>
                  <li className="text-[12px] flex items-start gap-2" style={{ color: C.coffee, lineHeight: 1.5 }}>
                    <span aria-hidden style={{ marginTop: 6, width: 4, height: 4, borderRadius: 99, background: C.gold, flexShrink: 0 }} />
                    <span><strong>Send the balance payment link</strong> above — your client taps to pay and it reconciles here automatically.</span>
                  </li>
                  <li className="text-[12px] flex items-start gap-2" style={{ color: C.coffee, lineHeight: 1.5 }}>
                    <span aria-hidden style={{ marginTop: 6, width: 4, height: 4, borderRadius: 99, background: C.gold, flexShrink: 0 }} />
                    <span>Tap the card in the <strong>Stripe Dashboard app</strong>, then hit <em>Checkout</em> here and set the method to <strong>Tap to Pay</strong> so your books stay accurate.</span>
                  </li>
                </ul>
              </>
            )}
          </Card>
        )}

        {/* SEND NOTIFICATION modal — styled choice for book / update /
            cancel, with an optional message (confirmation emails only). */}
        {notifyPrompt && (
          <div
            onClick={() => resolveNotify(false)}
            style={{ position: "fixed", inset: 0, zIndex: 90, background: "rgba(21,17,26,0.5)", display: "flex", alignItems: "flex-end", justifyContent: "center" }}
          >
            <div
              onClick={(e) => e.stopPropagation()}
              style={{ width: "100%", maxWidth: 480, background: C.cream, borderTopLeftRadius: 22, borderTopRightRadius: 22, boxShadow: "0 -8px 40px -12px rgba(0,0,0,0.3)", padding: "8px 20px calc(20px + env(safe-area-inset-bottom, 0px))" }}
            >
              <div className="flex items-center justify-between" style={{ padding: "12px 0 4px" }}>
                <h2 style={{ fontFamily: FONT_DISPLAY, fontSize: 20, fontWeight: 700, color: C.espresso, margin: 0 }}>Send notification</h2>
                <button type="button" onClick={() => resolveNotify(false)} aria-label="Close" style={{ background: "transparent", border: 0, color: C.coffee, padding: 6, cursor: "pointer" }}>
                  <X size={20} />
                </button>
              </div>
              <p className="text-[13px]" style={{ color: C.coffee, lineHeight: 1.5 }}>
                {notifyPrompt.kind === "book" && `Email ${notifyPrompt.who} a booking confirmation${notifyPrompt.smsToo ? " and text" : ""}? ${notifyPrompt.contractNote}`}
                {notifyPrompt.kind === "update" && `Email ${notifyPrompt.who} that their appointment was updated?`}
                {notifyPrompt.kind === "cancel" && `Email ${notifyPrompt.who} that their appointment was cancelled?`}
              </p>
              {notifyPrompt.allowMessage && (
                <div className="mt-3.5">
                  <p className="text-[10px] uppercase tracking-widest font-bold mb-1.5" style={{ color: C.muted, letterSpacing: "0.12em" }}>Add a message (optional)</p>
                  <Textarea
                    value={notifyMessage}
                    onChange={(e: any) => setNotifyMessage(e.target.value)}
                    placeholder="Appears at the top of the confirmation email — e.g. arrival or prep notes."
                    rows={3}
                  />
                </div>
              )}
              <div className="grid grid-cols-2 gap-3 mt-4">
                <Button variant="outline" onClick={() => resolveNotify(false)}>Don&apos;t notify</Button>
                <Button variant="primary" icon={<Send size={16} />} onClick={() => resolveNotify(true)}>Send</Button>
              </div>
            </div>
          </div>
        )}

        {/* RECURRING — appointments only */}
        {isAppointment && (
        <Card className="p-4">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <Repeat size={16} style={{ color: C.gold }} />
              <span className="font-semibold text-sm" style={{ color: C.espresso }}>Make recurring</span>
            </div>
            <Toggle checked={makeRecurring} onChange={setMakeRecurring} />
          </div>
          {makeRecurring && (
            <div className="space-y-3 mt-3">
              <Field label="Cadence">
                <Select value={cadence} onChange={e => setCadence(e.target.value)} options={RECURRENCE_OPTIONS} />
              </Field>
              {cadence === "custom" && (
                <Field label="Every"><MoneyInput prefix="" suffix="days" allowDecimal={false} value={customDays} onChange={setCustomDays} /></Field>
              )}
              <Field label="Occurrences" hint="this one + future">
                <MoneyInput prefix="" suffix="appts" allowDecimal={false} value={occurrences} onChange={setOccurrences} />
              </Field>
              <p className="text-xs" style={{ color: C.muted }}>
                Future appointments will be auto-created on the selected cadence. Edit each one individually as needed.
              </p>
            </div>
          )}
        </Card>
        )}

        {/* CLIENT NOTIFICATIONS — say yes/no to emailing the client about
            this booking or change, and see the contract that goes with it. */}
        {isAppointment && (
        <Card className="p-4">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2 min-w-0">
              <Mail size={16} style={{ color: C.gold }} />
              <span className="font-semibold text-sm" style={{ color: C.espresso }}>Notify client</span>
            </div>
            <Toggle checked={notifyClient} onChange={setNotifyClient} />
          </div>
          <p className="text-[11px] mt-1.5" style={{ color: C.muted, lineHeight: 1.45 }}>
            {notifyClient
              ? "When you save or cancel, we'll ask first — so you choose whether to email the client each time."
              : "Off — saving or cancelling won't email the client and won't ask. Good for placeholders or fixing a mistake quietly."}
          </p>
          {apptContractNames.length > 0 && (
            <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${C.hairline}` }}>
              <p className="text-[10px] uppercase tracking-widest font-bold" style={{ color: C.muted, letterSpacing: "0.12em" }}>
                Contract{apptContractNames.length === 1 ? "" : "s"} sent with this booking
              </p>
              {apptContractNames.map((n) => (
                <p key={n} className="text-[13px] mt-1 font-semibold" style={{ color: C.espresso }}>{n}</p>
              ))}
              <p className="text-[11px] mt-0.5" style={{ color: C.muted }}>Assigned in Settings → Services / Contracts.</p>
            </div>
          )}
        </Card>
        )}

        {/* REMINDERS — appointments only */}
        {isAppointment && (
        <Card className="p-4">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <Bell size={16} style={{ color: C.gold }} />
              <span className="font-semibold text-sm" style={{ color: C.espresso }}>Auto-remind this client</span>
            </div>
            <Toggle checked={remindersEnabled} onChange={setRemindersEnabled} />
          </div>
          {remindersEnabled && (
            <div className="space-y-2 mt-3">
              <p className="text-xs" style={{ color: C.muted }}>
                Reminders will be scheduled per your default settings (
                {[
                  reminderSettings.timings.confirmation && "on booking",
                  reminderSettings.timings.h48 && "48h",
                  reminderSettings.timings.h24 && "24h",
                  reminderSettings.timings.sameDay && `${reminderSettings.timings.sameDayHoursBefore}h prior`,
                ].filter(Boolean).join(", ")}). Manage in Reminder Settings.
              </p>
            </div>
          )}
          {SMS_ENABLED && (form.clientPhone || "").trim() && (
            <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${C.hairline}` }}>
              <div className="flex items-center justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <span className="font-semibold text-sm" style={{ color: C.espresso }}>Text reminders too</span>
                  <p className="text-[11px] mt-0.5" style={{ color: C.muted }}>
                    SMS confirmation + reminders for this client. Enable only with their consent — uses 1 SMS credit per text.
                  </p>
                </div>
                <Toggle checked={smsOptIn} onChange={setSmsOptIn} />
              </div>
            </div>
          )}
        </Card>
        )}

        <Field label="Notes">
          <Textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Hair texture, prep notes, anything to remember…" rows={3} />
        </Field>

        {isAppointment && (
          <Field label="How did they find you?">
            <div className="flex flex-wrap gap-2">
              {REFERRAL_SOURCE_PRESETS.map(s => {
                const on = normalizeReferralSource(form.referralSource) === s.value;
                return (
                  <button
                    type="button"
                    key={s.value}
                    onClick={() => setForm({ ...form, referralSource: on ? "" : s.value })}
                    className="px-3 py-1.5 rounded-full text-[12px] font-semibold active:scale-[0.97] transition"
                    style={{
                      background: on ? C.gold : C.paper,
                      color: on ? "#FFFFFF" : C.coffee,
                      border: `1px solid ${on ? C.gold : C.hairline}`,
                    }}
                  >
                    {s.label}
                  </button>
                );
              })}
            </div>
            <p className="text-[11px] mt-2" style={{ color: C.muted }}>
              Tag the source to see what fills your chair in Analytics. Bookings from your link are tagged automatically.
            </p>
          </Field>
        )}

        {isAppointment && form.id && form.paymentStatus !== "paid" && form.status !== "no_show" && !isCanceledAppointment(form) && parseMoney(form.totalPrice) > 0 && (
          <button
            type="button"
            onClick={handleCheckout}
            className="w-full font-semibold rounded-xl px-5 py-3.5 text-[15px] transition active:scale-[0.97] flex items-center justify-center gap-2"
            style={{
              background: "linear-gradient(135deg, #22C55E 0%, #16A34A 100%)",
              color: "#FFFFFF",
              border: "1.5px solid transparent",
              boxShadow: "0 10px 24px -10px rgba(34, 197, 94, 0.5)",
              letterSpacing: "0.01em",
            }}
          >
            <DollarSign size={18} />
            {balanceDue > 0 ? `Checkout · ${fmtMoney(balanceDue, business?.currency)}` : "Checkout"}
          </button>
        )}
        {/* Action menu — icon-chip rows matching the "all from your
            chair" features-page mockup. Same actions as before. */}
        {form.id && (
          <Card className="p-1.5">
            {isAppointment && form.clientId && (
              <ApptActionRow
                icon={<RefreshCw size={16} />} iconColor="#16A34A" chip="rgba(34,197,94,0.16)"
                title="Rebook next visit" sub="Book their next install"
                onClick={handleRebook} chevron
              />
            )}
            {isAppointment && (
              <ApptActionRow
                icon={<ArrowLeftRight size={16} />} iconColor="#EA6A2E" chip="rgba(255,122,69,0.16)"
                title="Move" sub="Reschedule to a different time"
                onClick={openQuickReschedule} chevron
              />
            )}
            {isAppointment && (
              <ApptActionRow
                icon={<Copy size={16} />} iconColor="#7C3AED" chip="rgba(124,58,237,0.12)"
                title="Duplicate" sub="Copy to a new booking"
                onClick={handleDuplicate} chevron
              />
            )}
            {isAppointment && (
              <ApptActionRow
                icon={<TimerIcon size={16} />} iconColor={C.espresso} chip="rgba(21,17,26,0.08)"
                title="Start chair timer" sub="Track time in the chair"
                onClick={handleStartTimer} chevron
              />
            )}
            {isAppointment && openCommunication && (
              <ApptActionRow
                icon={<MessageSquare size={16} />} iconColor="#6366F1" chip="rgba(99,102,241,0.16)"
                title="Send message" sub="Text or email this client"
                onClick={() => openCommunication({
                  appointment: form,
                  client: clients.find((c: any) => c.id === form.clientId),
                })}
                chevron
              />
            )}
            {form.date && (
              <ApptActionRow
                icon={<CalendarPlus size={16} />} iconColor="#B7791F" chip="rgba(251,191,36,0.18)"
                title="Add to calendar" sub="Add to your phone calendar"
                onClick={() => {
                  const ics = buildVCalendar([form as IcsAppointment], { businessName: form.eventTitle || business?.businessName, currency: business?.currency });
                  const fname = sanitizeFilename(`appt-${form.eventTitle || form.clientName || "event"}-${form.date}`) + ".ics";
                  addToCalendar(fname, ics);
                }}
                chevron
              />
            )}
          </Card>
        )}
        {isAppointment && form.id && (
          <AppointmentCommHistory appointmentId={form.id} commLog={store.commLog || []} />
        )}

        <div className="grid grid-cols-2 gap-3 pt-2">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button
            variant="primary"
            onClick={handleSave}
            disabled={isAppointment
              ? (!form.style && !form.clientId && !showNewClient)
              : !((form.eventTitle || "").trim())
            }
          >
            Save
          </Button>
        </div>
        {form.id && (
          <Card className="p-1.5">
            <ApptActionRow
              icon={<Trash2 size={16} />} iconColor={C.danger} chip="rgba(255,77,109,0.14)"
              title={isPersonal ? "Delete this event" : isBlocked ? "Remove blocked time" : "Cancel appointment"}
              sub={isPersonal || isBlocked ? undefined : "Keeps it in your books as cancelled"}
              onClick={handleDelete} danger
            />
            {isAppointment && (
              <ApptActionRow
                icon={<Trash2 size={16} />} iconColor={C.danger} chip="rgba(255,77,109,0.14)"
                title="Delete permanently" sub="Remove from history and reports"
                onClick={handleHardDelete} danger
              />
            )}
            {form.seriesId && (
              <ApptActionRow
                icon={<RefreshCw size={16} />} iconColor={C.danger} chip="rgba(255,77,109,0.14)"
                title="Cancel entire series" sub="Cancel all future occurrences"
                onClick={handleDeleteSeries} danger
              />
            )}
          </Card>
        )}
      </div>
      <QuickRescheduleSheet
        open={showQuickReschedule}
        date={rescheduleDate}
        time={rescheduleTime}
        onChangeDate={setRescheduleDate}
        onChangeTime={setRescheduleTime}
        onClose={() => setShowQuickReschedule(false)}
        onSave={handleQuickReschedule}
        busy={rescheduleBusy}
      />
      {showMaterialsFor && (
        <MaterialsUsedSheet
          appointment={showMaterialsFor}
          services={(store.servicesApi?.services as Service[]) || []}
          inventory={(store.inventoryItems || []) as InventoryItem[]}
          onClose={() => { setShowMaterialsFor(null); onClose(); }}
        />
      )}
    </Sheet>
  );
};

// ---- Quick Reschedule mini-sheet --------------------------------------
// Tiny date+time picker for the "client wants to move their slot"
// flow. Doesn't touch the rest of the appointment record.
const QuickRescheduleSheet = ({
  open, date, time, onChangeDate, onChangeTime, onClose, onSave, busy,
}: {
  open: boolean;
  date: string;
  time: string;
  onChangeDate: (v: string) => void;
  onChangeTime: (v: string) => void;
  onClose: () => void;
  onSave: () => void;
  busy: boolean;
}) => {
  return (
    <Sheet open={open} onClose={onClose} title="Reschedule">
      <div className="space-y-3 pb-2">
        <p className="text-[12px]" style={{ color: C.muted }}>
          Move this appointment to a new date and time. Everything else
          (client, style, deposit) stays put.
        </p>
        <div className="grid grid-cols-2 gap-3">
          <Field label="New date">
            <Input type="date" value={date} onChange={e => onChangeDate(e.target.value)} />
          </Field>
          <Field label="New time">
            <Input type="time" value={time} onChange={e => onChangeTime(e.target.value)} />
          </Field>
        </div>
        <div className="grid grid-cols-2 gap-3 pt-1">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button variant="primary" onClick={onSave} disabled={busy || !date || !time}>
            {busy ? "Saving…" : "Reschedule"}
          </Button>
        </div>
      </div>
    </Sheet>
  );
};

// ============================================================
//  CLIENTS
// ============================================================
const PREF_STYLES = ["Knotless", "Box braids", "Boho", "Goddess", "Stitch braids", "Cornrows", "Twists", "Locs", "Sew-in", "Wig install"];
const SENSITIVITY = ["None", "Mild", "Moderate", "High"];

// ============================================================
//  CUSTOMERS — mobile-first refresh
// ============================================================
//
// Top-level layout:
//   - Large display title + circular overflow button
//   - Search input + slim filter button on the same row
// Layered interactions:
//   - Overflow popover (Create / Manage groups / Merge)
//   - Filters bottom sheet (uses the shared <Sheet> so safe-area
//     spacing carries over for free)
//
// Existing CRUD stays as-is via ClientSheet; this is a UX-only
// upgrade to the list screen.

type CustomerLastVisited = "any" | "30d" | "90d" | "year" | "never";
type CustomerFrequency = "any" | "1plus" | "3plus" | "5plus";

type CustomerFilters = {
  lastVisited: CustomerLastVisited;
  frequency: CustomerFrequency;
};

const DEFAULT_CUSTOMER_FILTERS: CustomerFilters = {
  lastVisited: "any",
  frequency: "any",
};

const filtersAreActive = (f: CustomerFilters) =>
  f.lastVisited !== "any" || f.frequency !== "any";

const Clients = ({ store, openClientPhotos, openCommunication, openQuickAppt, savePhoto, deletePhoto: deletePhotoProp, openClientId, clearOpenClientId, openAppointmentRecord }: { store: any; openClientPhotos?: any; openCommunication?: (ctx: CommContext) => void; openQuickAppt?: (prefill?: any) => void; savePhoto?: (p: any) => Promise<any>; deletePhoto?: (id: string) => Promise<void>; openClientId?: string | null; clearOpenClientId?: () => void; openAppointmentRecord?: (a: any) => void }) => {
  void openClientPhotos;
  const { clients, appointments, photos, business } = store;
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<EntityRecord | null>(null);
  const [profileFor, setProfileFor] = useState<EntityRecord | null>(null);
  const [showOverflow, setShowOverflow] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState<CustomerFilters>(DEFAULT_CUSTOMER_FILTERS);
  const [comingSoon, setComingSoon] = useState<string | null>(null);

  // Notification deep-link consumer: when App stamps openClientId,
  // find the matching client record and open the rich profile sheet
  // (not the bare edit sheet). Clear the prop after so re-renders
  // don't re-open it.
  useEffect(() => {
    if (!openClientId) return;
    const found = clients.find((c: any) => c?.id === openClientId);
    if (found) setProfileFor(found);
    clearOpenClientId?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional one-shot consumer
  }, [openClientId, clients]);

  const today = todayISO();
  const enriched = useMemo(() => clients.map(c => {
    // Drop personal/blocked rows even if one got tagged to this client
    // by accident — they should never bump apptCount or visit dates.
    const cAppts = appointments.filter(a =>
      a.clientId === c.id && (!a.kind || a.kind === "appointment"));
    // Lifetime total = sum of what was actually collected, not quoted.
    const totalSpent = cAppts
      .filter(a => (a.status === "completed" || a.paymentStatus === "paid") && !isCanceledAppointment(a))
      .reduce((s, a) => {
        const collected = calculateCollectedAmount(a);
        return s + collected;
      }, 0);

    // Compute past / today / future relative to the local-date `today`
    // so the row label can pick the right preposition. ISO strings are
    // YYYY-MM-DD lexically comparable when generated from local time
    // (todayISO + a.date both use localDateISO()), so plain string
    // comparison is timezone-safe here.
    const dates = cAppts
      .map(a => a.date)
      .filter((d: any): d is string => typeof d === "string" && d.length >= 8)
      .filter(d => {
        // Exclude cancelled bookings — a future cancellation shouldn't
        // surface as the next "upcoming" visit.
        const a = cAppts.find(x => x.date === d);
        return !a || !isCanceledAppointment(a);
      })
      .sort();
    const pastDates = dates.filter(d => d < today);
    const todayDates = dates.filter(d => d === today);
    const futureDates = dates.filter(d => d > today);

    const lastPastDate = pastDates.length > 0 ? pastDates[pastDates.length - 1] : undefined;
    const todayDate = todayDates[0];
    const nextFutureDate = futureDates[0];

    return {
      ...c,
      apptCount: cAppts.length,
      totalSpent,
      lastPastDate,
      todayDate,
      nextFutureDate,
      photoCount: photos.filter(p => p.clientId === c.id).length,
    };
  }).sort((a, b) => {
    // Alphabetize A → Z, case- and diacritic-insensitive, whitespace
    // trimmed. Clients with missing/blank names sink to the bottom so
    // the list reads like a contact book. `useMemo` above + the
    // `.map(...)` array means we're not mutating the original
    // store.clients array.
    const an = (a.name || "").trim();
    const bn = (b.name || "").trim();
    if (!an && !bn) return 0;
    if (!an) return 1;
    if (!bn) return -1;
    return an.localeCompare(bn, undefined, { sensitivity: "base", numeric: true });
  }), [clients, appointments, photos, today]);

  const filtered = useMemo(() => {
    return enriched.filter(c => {
      if (search && !c.name.toLowerCase().includes(search.toLowerCase())) return false;
      // Last visited filter is about ACTUAL past visits — ignore
      // upcoming bookings so a client booked next month doesn't count
      // as having "visited" recently.
      if (filters.lastVisited !== "any") {
        if (!c.lastPastDate && !c.todayDate) {
          if (filters.lastVisited !== "never") return false;
        } else {
          if (filters.lastVisited === "never") return false;
          const days = filters.lastVisited === "30d" ? 30 : filters.lastVisited === "90d" ? 90 : 365;
          const cutoff = addDaysISO(today, -days);
          const ref = c.todayDate || c.lastPastDate;
          if (!ref || ref < cutoff) return false;
        }
      }
      // Frequency
      if (filters.frequency !== "any") {
        const min = filters.frequency === "1plus" ? 1 : filters.frequency === "3plus" ? 3 : 5;
        if (c.apptCount < min) return false;
      }
      return true;
    });
  }, [enriched, search, filters, today]);

  const filtersOn = filtersAreActive(filters);

  return (
    <div className="bbp-fade pb-32">
      {/* HEADER */}
      <div className="px-5 pt-6 pb-3 flex items-start justify-between">
        <div className="min-w-0">
          <div className="mb-1"><SectionEyebrow>Your book</SectionEyebrow></div>
          <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 34, fontWeight: 600, color: C.espresso, lineHeight: 1 }}>
            Customers
          </h1>
          <p className="text-[12px] mt-1" style={{ color: C.muted }}>
            {clients.length} {clients.length === 1 ? "person" : "people"}
            {filtered.length !== clients.length ? ` · ${filtered.length} shown` : ""}
          </p>
        </div>
        <div className="relative">
          <button
            type="button"
            onClick={() => setShowOverflow(v => !v)}
            aria-label="Customers menu"
            aria-expanded={showOverflow}
            className="rounded-full active:scale-[0.96] transition flex items-center justify-center"
            style={{
              width: 40, height: 40,
              background: C.paper,
              border: `1px solid ${C.hairline}`,
              boxShadow: "0 1px 2px rgba(21, 17, 26, 0.04), 0 6px 18px -10px rgba(21, 17, 26, 0.18)",
              color: C.coffee,
            }}
          >
            <MoreHorizontal size={18} />
          </button>
          {showOverflow && (
            <CustomersOverflowMenu
              onClose={() => setShowOverflow(false)}
              onCreate={() => { setShowOverflow(false); setEditing({}); }}
              onManageGroups={() => { setShowOverflow(false); setComingSoon("Customer groups"); }}
              onMerge={() => { setShowOverflow(false); setComingSoon("Merge customers"); }}
            />
          )}
        </div>
      </div>

      {/* SEARCH + FILTER */}
      <div className="px-5 pb-3 flex items-center gap-2">
        <div className="relative flex-1">
          <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2" style={{ color: C.muted }} />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search customers"
            inputMode="search"
            autoComplete="off"
            className="w-full rounded-xl py-3 pl-10 pr-4 text-[15px] outline-none"
            style={{ background: C.paper, border: `1px solid ${C.hairline}`, color: C.ink }}
          />
        </div>
        <button
          type="button"
          onClick={() => setShowFilters(true)}
          aria-label="Filter customers"
          className="rounded-xl active:scale-[0.97] transition flex items-center gap-1.5 px-3"
          style={{
            height: 46,
            background: filtersOn ? C.espresso : C.paper,
            border: `1px solid ${filtersOn ? C.espresso : C.hairline}`,
            color: filtersOn ? C.cream : C.coffee,
          }}
        >
          <SlidersHorizontal size={16} />
          <span className="text-[12px] font-semibold">Filter</span>
          {filtersOn && (
            <span
              aria-hidden
              style={{
                width: 6, height: 6, borderRadius: 999,
                background: C.gold, marginLeft: 2,
              }}
            />
          )}
        </button>
      </div>

      {/* LIST */}
      <div className="px-5 space-y-2">
        {filtered.length === 0 ? (
          clients.length === 0 ? (
            <EmptyState
              icon={<Users size={28} style={{ color: C.gold }} />}
              title="Every booked braid starts with one client"
              body="Build your book of business. Every customer becomes a profile with style preferences, photos, allergies, and lifetime value."
              cta={<Button variant="primary" icon={<Plus size={18} />} onClick={() => setEditing({})}>Add first customer</Button>}
            />
          ) : (
            <div className="text-center py-10">
              <p style={{ fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 600, color: C.espresso }}>No matches</p>
              <p className="text-[13px] mt-2" style={{ color: C.muted }}>
                {search ? `Nothing matches "${search}"` : "Try clearing filters."}
              </p>
              {filtersOn && (
                <div className="mt-4 inline-block">
                  <Button variant="outline" onClick={() => setFilters(DEFAULT_CUSTOMER_FILTERS)}>Clear filters</Button>
                </div>
              )}
            </div>
          )
        ) : (
          filtered.map(c => (
            <button
              type="button"
              key={c.id}
              onClick={() => setProfileFor(c)}
              className="w-full text-left active:scale-[0.99] transition"
              style={{
                background: C.paper,
                border: `1px solid ${C.hairline}`,
                borderRadius: 18,
                padding: "14px 16px",
                boxShadow: "0 1px 2px rgba(21, 17, 26, 0.04)",
                fontFamily: "inherit",
                color: "inherit",
                appearance: "none",
                WebkitAppearance: "none",
              }}
            >
              <div className="flex items-center gap-3.5" style={{ pointerEvents: "none" }}>
                <div
                  className="rounded-full flex items-center justify-center shrink-0"
                  style={{
                    width: 52, height: 52,
                    background: `linear-gradient(135deg, ${C.brandPrimary}, ${C.brandPrimaryDeep})`,
                    color: C.cream,
                    fontFamily: FONT_DISPLAY, fontSize: 19, fontWeight: 600,
                  }}
                >
                  {initials(c.name)}
                </div>
                <div className="flex-1 min-w-0">
                  <p
                    className="truncate"
                    style={{ fontFamily: FONT_DISPLAY, fontSize: 18, fontWeight: 600, color: C.espresso, lineHeight: 1.15 }}
                  >
                    {c.name}
                  </p>
                  <p className="text-[12px] mt-0.5 truncate" style={{ color: C.muted }}>
                    {c.apptCount > 0
                      ? `${c.apptCount} ${c.apptCount === 1 ? "visit" : "visits"}`
                      : "No visits yet"}
                    {(() => {
                      // Pick one date to surface in the subtitle.
                      // Priority: today → upcoming → most recent past.
                      // Each renders with the correct preposition so a
                      // future booking is never labeled "last".
                      if (c.todayDate) return " · today";
                      if (c.nextFutureDate) return ` · upcoming ${fmtDate(c.nextFutureDate)}`;
                      if (c.lastPastDate) return ` · last ${fmtDate(c.lastPastDate)}`;
                      return "";
                    })()}
                    {c.photoCount > 0 ? ` · ${c.photoCount} photo${c.photoCount === 1 ? "" : "s"}` : ""}
                  </p>
                </div>
                <div className="text-right shrink-0">
                  <p className="text-[9px] uppercase tracking-widest font-bold" style={{ color: C.muted, letterSpacing: "0.14em" }}>Lifetime</p>
                  <p style={{ fontFamily: FONT_DISPLAY, fontSize: 18, fontWeight: 600, color: C.goldDeep, lineHeight: 1 }}>
                    {fmtMoney(c.totalSpent, business.currency)}
                  </p>
                </div>
              </div>
            </button>
          ))
        )}
      </div>

      <FAB onClick={() => setEditing({})} />

      <ClientProfileSheet
        open={!!profileFor}
        // Re-derive the live record from the store so edits made inside
        // the sheet (tags, comm preference, rebooking reminders…) reflect
        // immediately — profileFor is a snapshot taken when the sheet
        // opened and doesn't update when store.clients changes.
        client={profileFor ? (((store.clients as any[]) || []).find((c: any) => c?.id === profileFor.id) || profileFor) : null}
        store={store}
        onClose={() => setProfileFor(null)}
        onEdit={() => { const c = profileFor; setProfileFor(null); setEditing(c); }}
        onOpenAppointment={(a) => { setProfileFor(null); openAppointmentRecord?.(a); }}
        onMessage={openCommunication}
        onBookAppointment={(prefill) => { setProfileFor(null); openQuickAppt?.(prefill); }}
      />

      <ClientSheet
        open={!!editing}
        client={editing}
        store={store}
        onClose={() => setEditing(null)}
        openCommunication={openCommunication}
        openQuickAppt={openQuickAppt}
        savePhoto={savePhoto}
        deletePhotoExternal={deletePhotoProp}
      />

      <CustomersFilterSheet
        open={showFilters}
        filters={filters}
        onChange={setFilters}
        onClear={() => setFilters(DEFAULT_CUSTOMER_FILTERS)}
        onApply={() => setShowFilters(false)}
        onClose={() => setShowFilters(false)}
        onComingSoon={(label) => setComingSoon(label)}
      />

      <Sheet
        open={!!comingSoon}
        onClose={() => setComingSoon(null)}
        title={comingSoon || ""}
      >
        <div className="space-y-3 pb-2">
          <p className="text-[14px]" style={{ color: C.coffee, lineHeight: 1.5 }}>
            <strong>{comingSoon}</strong> is on the roadmap. Tap the heart in the
            Account screen to vote it up the queue, or use Search and the existing
            filters in the meantime.
          </p>
          <Button variant="primary" fullWidth onClick={() => setComingSoon(null)}>
            Got it
          </Button>
        </div>
      </Sheet>
    </div>
  );
};

// ---- Customers overflow popover ---------------------------------------
const CustomersOverflowMenu = ({
  onClose, onCreate, onManageGroups, onMerge,
}: {
  onClose: () => void;
  onCreate: () => void;
  onManageGroups: () => void;
  onMerge: () => void;
}) => {
  const ref = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    const onPointer = (e: PointerEvent) => {
      const node = ref.current;
      if (!node) return;
      if (e.target instanceof Node && !node.contains(e.target)) onClose();
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("pointerdown", onPointer, true);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer, true);
      document.removeEventListener("keydown", onKey);
    };
  }, [onClose]);

  const items = [
    { icon: <UserPlus size={18} />, label: "Create customer",  description: "Add a profile manually",      enabled: true,  onClick: onCreate },
    { icon: <Users size={18} />,    label: "Manage groups",     description: "Coming soon",                 enabled: false, onClick: onManageGroups },
    { icon: <Repeat size={18} />,   label: "Merge customers",   description: "Coming soon",                 enabled: false, onClick: onMerge },
  ];

  return (
    <div
      ref={ref}
      role="menu"
      className="absolute z-50 mt-2 right-0 w-64 rounded-2xl overflow-hidden bbp-pop"
      style={{
        background: C.paper,
        border: `1px solid ${C.hairline}`,
        boxShadow:
          "0 1px 2px rgba(21, 17, 26, 0.06), 0 18px 36px -12px rgba(21, 17, 26, 0.22)",
        transformOrigin: "top right",
      }}
    >
      <style>{`@keyframes bbpPop { from { opacity:0; transform: scale(0.96) translateY(-4px);} to { opacity:1; transform: scale(1) translateY(0);} } .bbp-pop { animation: bbpPop 0.18s ease-out both; }`}</style>
      {items.map((it, i) => (
        <button
          key={it.label}
          type="button"
          role="menuitem"
          onClick={it.onClick}
          className="w-full flex items-center gap-3 px-4 py-3 active:scale-[0.99] transition text-left"
          style={{
            color: C.espresso,
            borderTop: i === 0 ? "none" : `1px solid ${C.hairline}`,
            background: "transparent",
            opacity: it.enabled ? 1 : 0.55,
          }}
        >
          <span
            aria-hidden
            className="flex items-center justify-center shrink-0"
            style={{
              width: 32, height: 32, borderRadius: 999,
              background: C.ivory, color: C.gold, border: `1px solid ${C.hairline}`,
            }}
          >
            {it.icon}
          </span>
          <span className="flex-1 min-w-0">
            <span className="block text-[13px] font-semibold leading-tight" style={{ color: C.espresso }}>
              {it.label}
            </span>
            <span className="block text-[11px] mt-0.5" style={{ color: C.muted }}>
              {it.description}
            </span>
          </span>
        </button>
      ))}
    </div>
  );
};

// ---- Customers filter bottom sheet ------------------------------------
const CustomersFilterSheet = ({
  open, filters, onChange, onClear, onApply, onClose, onComingSoon,
}: {
  open: boolean;
  filters: CustomerFilters;
  onChange: (f: CustomerFilters) => void;
  onClear: () => void;
  onApply: () => void;
  onClose: () => void;
  onComingSoon: (label: string) => void;
}) => {
  const radio = <T extends string>(
    label: string,
    value: T,
    current: T,
    onPick: (v: T) => void,
  ) => (
    <button
      type="button"
      key={value}
      onClick={() => onPick(value)}
      className="px-3 py-1.5 rounded-full text-[12px] font-semibold active:scale-[0.97] transition"
      style={{
        background: current === value ? C.espresso : C.paper,
        color: current === value ? C.cream : C.coffee,
        border: `1px solid ${current === value ? C.espresso : C.hairline}`,
      }}
    >
      {label}
    </button>
  );

  const SoonRow = ({ label }: { label: string }) => (
    <button
      type="button"
      onClick={() => onComingSoon(label)}
      className="w-full text-left rounded-xl px-4 py-3 flex items-center justify-between active:scale-[0.99] transition"
      style={{ background: C.paper, border: `1px solid ${C.hairline}`, opacity: 0.7 }}
    >
      <div>
        <p className="text-[13px] font-semibold" style={{ color: C.espresso }}>{label}</p>
        <p className="text-[11px] mt-0.5" style={{ color: C.muted }}>Coming soon</p>
      </div>
      <ChevronRight size={16} style={{ color: C.muted }} />
    </button>
  );

  return (
    <Sheet
      open={open}
      onClose={onClose}
      title="Filters"
      rightAction={
        <button
          type="button"
          onClick={onClear}
          className="text-[12px] font-semibold px-2 py-1 rounded-lg"
          style={{ color: C.coffee }}
        >
          Clear all
        </button>
      }
    >
      <div className="space-y-5 pb-2">
        <div>
          <p className="text-[10px] uppercase tracking-widest font-bold mb-2" style={{ color: C.muted, letterSpacing: "0.14em" }}>
            Last visited
          </p>
          <div className="flex flex-wrap gap-2">
            {radio("Any time", "any" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
            {radio("Past 30 days", "30d" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
            {radio("Past 90 days", "90d" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
            {radio("Past year", "year" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
          </div>
        </div>

        <div>
          <p className="text-[10px] uppercase tracking-widest font-bold mb-2" style={{ color: C.muted, letterSpacing: "0.14em" }}>
            Hasn&rsquo;t visited
          </p>
          <p className="text-[12px] mb-2" style={{ color: C.muted }}>
            Show customers who&rsquo;ve never booked.
          </p>
          <div className="flex flex-wrap gap-2">
            {radio("Off", "any" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
            {radio("Never visited", "never" as CustomerLastVisited, filters.lastVisited, v => onChange({ ...filters, lastVisited: v }))}
          </div>
        </div>

        <div>
          <p className="text-[10px] uppercase tracking-widest font-bold mb-2" style={{ color: C.muted, letterSpacing: "0.14em" }}>
            Visit frequency
          </p>
          <div className="flex flex-wrap gap-2">
            {radio("Any", "any" as CustomerFrequency, filters.frequency, v => onChange({ ...filters, frequency: v }))}
            {radio("1+ visits", "1plus" as CustomerFrequency, filters.frequency, v => onChange({ ...filters, frequency: v }))}
            {radio("3+ visits", "3plus" as CustomerFrequency, filters.frequency, v => onChange({ ...filters, frequency: v }))}
            {radio("5+ visits", "5plus" as CustomerFrequency, filters.frequency, v => onChange({ ...filters, frequency: v }))}
          </div>
        </div>

        <div>
          <p className="text-[10px] uppercase tracking-widest font-bold mb-2" style={{ color: C.muted, letterSpacing: "0.14em" }}>
            More filters
          </p>
          <div className="space-y-2">
            <SoonRow label="Card on file" />
            <SoonRow label="Feedback" />
            <SoonRow label="Creation source" />
            <SoonRow label="Instant profile" />
            <SoonRow label="Visited location" />
          </div>
        </div>

        <Button variant="primary" fullWidth onClick={onApply}>
          Apply
        </Button>
      </div>
    </Sheet>
  );
};

